ms[ps.pid]=ps.nums
end
for qs,rs in pairs(pb.rules(Zr))do
if not ls[qs]then
local ss={}
for ts,us in pairs(type(ms[qs])==NQe[2348]and ms[qs]or{})do
ss[ts]=us
end
for vs,ws in pairs(type(rs.nums)==NQe[2348]and rs.nums or{})do
ss[vs]=ws
end
local xs=rs.trigger~=nil and tostring(rs.trigger):find(NQe[2766],1,true)~=nil
if rs.family==NQe[2548]then
local ys=(xs and pb.ABILITY_UPTIME or 1)*(rs.who==NQe[2616]and pb.RANGE_SHARE or 1)
local zs=es.aura or{typed={}}
for As,Bs in pairs(type(ss.typed)==NQe[2348]and ss.typed or{})do
zs.typed[As]=math.max(zs.typed[As]or 0,(tonumber(Bs)or 0)*ys)
