if Ds and Ds.kind==NQe[2535]and not(type(ss.shred)==NQe[2348])then
local Is=tonumber(ss.amp)
local Js=as and((type(as.ampTypes)==NQe[2348]and as.ampTypes[Ds.dtype])or(tonumber(as.amp)or 0)>0)
if Is and Is>0 and not Js then
es.fx,fs=(es.fx or 0)+Is*V.TYPED_AMP_SHARE*Hs*hs,true
end
elseif Ds and(Ds.kind==NQe[2483]or Ds.kind==NQe[2543])then
