function mb.skinPlan()
local ZG,aH=N.session(),N.prof()
local bH=N.data(NQe[2800])or{}
local cH=(aH.inventory and aH.inventory.unique_items)or aH.unique_items or{}
local dH,eH={},{kinds={},sell={},wear={},pearls=0,missing={}}
for fH,gH in pairs(cH)do
local hH=type(gH)==NQe[2348]and N.Items[gH.item_id]
if hH and hH.item_group==NQe[2800]and hH._skin_set==mb.SKIN_SET and hH.usage and bH[hH.usage.skin_id]then
local iH=dH[gH.item_id]
if not iH then
iH={id=gH.item_id,name=hH.name,rarity=hH.rarity,skinId=hH.usage.skin_id,skin=bH[hH.usage.skin_id],uuids={}}
dH[gH.item_id]=iH
table.insert(eH.kinds,iH)
end
table.insert(iH.uuids,gH.uuid or fH)
end
end
table.sort(eH.kinds,function(jH,kH)
return jH.name<kH.name
end)
local lH=mb.team()
local mH=ZG.profile_data.collection.owned_units
for nH,oH in ipairs(eH.kinds)do
for pH,qH in pairs(mH)do
if mb.skinFits(qH.unit_id,oH.skin)then
oH.fits=true
break
end
end
local rH=oH.rarity==NQe[2938]or oH.rarity==NQe[2939]
oH.keep=(oH.fits or rH)and 1 or 0
for sH=oH.keep+1,#oH.uuids do
table.insert(eH.sell,{uuid=oH.uuids[sH],name=oH.name,pearls=mb.SKIN_PRICE[oH.rarity]or 0})
eH.pearls=eH.pearls+(mb.SKIN_PRICE[oH.rarity]or 0)
end
end
for tH,uH in ipairs(lH)do
local vH=uH.skin and uH.skin._skin_id and bH[uH.skin._skin_id]
if not(vH and vH._skin_set==mb.SKIN_SET)then
for wH,xH in pairs(bH)do
if type(xH)==NQe[2348]and xH._skin_set==mb.SKIN_SET and mb.skinFits(uH.unit_id,xH)then
local yH=wH..NQe[2940]
if dH[yH]then
table.insert(eH.wear,{uuid=dH[yH].uuids[1],unit=uH.uuid,unitName=V.name(uH.unit_id),name=dH[yH].name})
else
table.insert(eH.missing,{item=yH,unitName=V.name(uH.unit_id),name=xH.name,boost=tonumber(xH._damage_boost)or 0,drop=mb.SKIN_DROP[xH._skin_rarity]or 0})
end
end
end
end
end
return eH
end
function mb.starPlan(zH)
zH=zH or mb.skinPlan()
local AH=N.Items[mb.STAR]or{}
local BH=tonumber(AH._mythic_unit_pity)or 400
local CH=(N.prof().capsule_pity_data or{})[mb.STAR]or{}
local DH=tonumber(CH.opens_since_mythic_unit)or 0
local EH={opened=tonumber(CH.total_opens)or 0,left=math.max(1,BH-DH),units={}}
local FH=tonumber(N.cur(NQe[2932]))or 0
EH.can=math.max(0,math.floor((FH-(tonumber(O.pearlFloor)or 0))/mb.STAR_COST))
local GH={}
for HH,IH in pairs(N.session().profile_data.collection.owned_units)do
GH[IH.unit_id]=true
local JH=N.Units[IH.unit_id]
if JH and JH.evolved and JH.evolved.from then
GH[JH.evolved.from]=true
end
end
for KH,LH in pairs(AH.usage and AH.usage.possible_rewards or{})do
local MH=LH.unit or LH.item
if MH and N.Units[MH]and N.Units[MH].rarity==NQe[2939]and not GH[MH]then
table.insert(EH.units,V.name(MH))
end
end
table.sort(EH.units)
local NH={}
if#zH.missing>0 then
local OH=zH.missing[1]
table.insert(NH,string.format(NQe[2941],OH.name,OH.unitName))
end
if#EH.units>0 then
table.insert(NH,string.format(NQe[2942],table.concat(EH.units,NQe[2472])))
end
EH.why=table.concat(NH,NQe[2943])
EH.open= #NH>0 and math.min(EH.can,#EH.units>0 and EH.left or 100)or 0
return EH
end
function mb.skinText()
local PH,QH=pcall(mb.skinPlan)
if not PH then
return NQe[2944]..tostring(QH)
end
local RH={}
local SH={}
for TH,UH in ipairs(QH.kinds)do
table.insert(SH,string.format(NQe[2945],UH.name,#UH.uuids>1 and(NQe[2946].. #UH.uuids)or NQe[1267],(tonumber(UH.skin._damage_boost)or 0)*100,UH.fits and NQe[1267]or NQe[2947]))
end
table.insert(RH,NQe[2948]..(#SH>0 and table.concat(SH,NQe[2472])or NQe[2949])..NQe[2950])
if#QH.wear>0 then
local VH={}
for WH,XH in ipairs(QH.wear)do
table.insert(VH,XH.name..NQe[2951]..XH.unitName)
end
table.insert(RH,NQe[2952]..table.concat(VH,NQe[2472])..NQe[2950])
end
for YH,ZH in ipairs(QH.missing)do
table.insert(RH,string.format(NQe[2953],ZH.name,ZH.unitName,ZH.boost*100,ZH.drop*100))
end
if#QH.sell>0 then
local _H={}
for aI,bI in ipairs(QH.sell)do
_H[bI.name]=(_H[bI.name]or 0)+1
end
local cI={}
for dI,eI in pairs(_H)do
table.insert(cI,eI..NQe[2954]..dI)
end
table.sort(cI)
table.insert(RH,string.format(NQe[2955],table.concat(cI,NQe[2472]),U.fmt(QH.pearls)))
else
table.insert(RH,NQe[2956])
end
local fI,gI=pcall(mb.starPlan,QH)
if fI then
table.insert(RH,string.format(NQe[2957],gI.opened,gI.left,U.fmt(gI.left*mb.STAR_COST)))
if gI.open>0 then
table.insert(RH,string.format(NQe[2958],gI.open,U.fmt(gI.open*mb.STAR_COST),gI.why,U.fmt(O.pearlFloor)))
elseif gI.why~=NQe[1267]then
table.insert(RH,string.format(NQe[2959],gI.why,U.fmt(O.pearlFloor)))
else
table.insert(RH,NQe[2960])
end
end
if ab.pickNote.skins then
table.insert(RH,ab.pickNote.skins)
end
return table.concat(RH,NQe[2363])
end
function mb.skinTick()
if not(O.skinSmart or O.starOpen)or not(P.live.event and mb.is(P.live.event.level))then
return
end
if(F.req.back.skins or 0)>U.now()then
return
end
local hI=N.session()
local function iI(jI,kI,lI)
local mI=F.gameSaid(kI)
ab.pickNote.skins=string.format(NQe[2961],jI,tostring(mI or lI or NQe[2902]))
F.log(1,NQe[2872],ab.pickNote.skins)
F.backoff(NQe[2962],1800)
end
local nI=mb.skinPlan()
if O.skinSmart then
local oI=nI.wear[1]
if oI and(F.req.back.skinWear or 0)<=U.now()then
local pI=kb.slotOf(oI.unit)
if pI then
P.str.reequip={uuid=oI.unit,slot=pI}
F.saveNow()
F.request(NQe[2963],NQe[2964],oI.unit)
local qI=U.now()
while U.now()-qI<4 and kb.slotOf(oI.unit)do
task.wait(0.25)
end
end
local rI=U.now()
local sI,tI=F.request(NQe[2965],NQe[2895],oI.uuid,{unit_uuid=oI.unit})
local function uI()
local vI=hI.collection:get_unit_by_uuid(oI.unit)
return vI and vI.skin~=nil
end
while U.now()-rI<5 and not uI()do
task.wait(0.25)
end
if pI then
kb.reequip()
end
if uI()then
F.log(1,NQe[2872],string.format(NQe[2966],oI.name,oI.unitName))
ab.pickNote.skins=nil
nI=mb.skinPlan()
else
local wI=F.gameSaid(rI)
ab.pickNote.skins=string.format(NQe[2967],oI.name,tostring(wI or tI or NQe[2902]))
F.log(1,NQe[2872],ab.pickNote.skins)
F.backoff(NQe[2965],1800)
end
end
if#nI.sell>0 then
local xI,yI={},0
for zI=1,math.min(50,#nI.sell)do
table.insert(xI,nI.sell[zI].uuid)
yI=yI+nI.sell[zI].pearls
end
local AI=tonumber(N.cur(NQe[2932]))or 0
local BI=U.now()
local CI,DI=F.request(NQe[2968],NQe[2900],xI)
while U.now()-BI<5 and(tonumber(N.cur(NQe[2932]))or 0)<=AI do
task.wait(0.25)
end
local EI=(tonumber(N.cur(NQe[2932]))or 0)-AI
if EI<=0 then
return iI(NQe[2969],BI,DI)
end
cb.add(string.format(NQe[2970],#xI),#xI,NQe[2962],string.format(NQe[2971],U.fmt(EI)))
ab.pickNote.skins=nil
end
end
if O.starOpen then
local FI=hI.inventory
local function GI()
local HI,II=pcall(FI.get_number_of_owned_item,FI,mb.STAR)
return HI and tonumber(II)or 0
end
local JI=U.now()
for KI=1,8 do
if U.now()-JI>15 or not F.alive or F.where~=NQe[2428]then
break
end
local LI=GI()
local MI=mb.starPlan(mb.skinPlan())
local NI=U.now()
if LI>0 then
local OI,PI=F.request(NQe[2972],NQe[2973],mb.STAR,{use10=LI>=10,use_all=false})
while U.now()-NI<6 and GI()>=LI do
task.wait(0.25)
end
if GI()>=LI then
return iI(NQe[2974],NI,PI)
end
F.log(1,NQe[2872],string.format(NQe[2975],LI-GI(),(tonumber(((N.prof().capsule_pity_data or{})[mb.STAR]or{}).total_opens)or 0)))
ab.pickNote.skins=nil
elseif MI.open>0 then
local QI=MI.open>=10 and 10 or 1
local RI=tonumber(N.cur(NQe[2932]))or 0
local SI,TI=F.request(NQe[2976],NQe[2977],mb.STAR,NQe[2371],NQe[2978],tostring(QI))
while U.now()-NI<5 and GI()<=0 do
task.wait(0.25)
end
if GI()<=0 then
return iI(NQe[2979],NI,TI)
end
cb.add(string.format(NQe[2980],GI()),RI-(tonumber(N.cur(NQe[2932]))or 0),NQe[2981],NQe[2982]..MI.why)
ab.pickNote.skins=nil
else
break
end
end
end
end
