local Pcb=Ocb<Dcb.max_level(Ncb)and Dcb.get_level(Ncb,Ocb+1)or nil
local Qcb=Pcb and tonumber(Pcb.cost)or nil
if Qcb and Qcb<=Kcb and(not Lcb or Qcb<Lcb.cost)then
Lcb={kind=Ncb,cost=Qcb,to=Ocb+1}
end
end
if Lcb then
Fcb.upgrade=Lcb
Kcb=Kcb-Lcb.cost
end
end
local Rcb=Dcb.ore_per_sword()
