end
table.sort(Agb)
local Dgb=table.concat(Agb,NQe[3055])
if not rgb and#(P.str.core or{})>=6 and os.time()-(tonumber(P.str.coreAt)or 0)<(O.teamCoreDays or 7)*86400 then
if P.str.teamSig==Dgb then
