end
if P.str.pendingSig~=Dgb then
P.str.pendingSig,P.str.pendingAt=Dgb,os.time()
return P.str.core
end
if os.time()-(tonumber(P.str.pendingAt)or 0)<600 then
return P.str.core
end
end
if not sgb then
P.str.pendingSig,P.str.pendingAt=nil,nil
end
local Egb,Fgb={},{}
for Ggb,Hgb in ipairs(ugb)do
table.insert(Egb,Hgb.uuid)
Fgb[Hgb.id]=true
end
for Igb,Jgb in ipairs({NQe[3464],NQe[3465]})do
local Kgb=O[Jgb]
local Lgb=type(Kgb)==NQe[1253]and Kgb~=NQe[1267]and tgb.collection:get_unit_by_uuid(Kgb)
if Lgb and not table.find(Egb,Kgb)then
