if Ugb and(Ugb.rarity==NQe[2939]or Ugb.rarity==NQe[3466])and not Fgb[Tgb.unit_id]and V.rows(Tgb.unit_id)and not V.hidden(Tgb.unit_id)and not V.isFarm(Tgb.unit_id)and not V.allyBuff(Tgb.unit_id)then
local Vgb=tgb.collection:get_unit_by_uuid(Sgb)or Tgb
