return kb.RELIC_SETTLED_GAIN
end
return kb.RELIC_MOVE_GAIN
end
function kb.relicWorth(khb,lhb)
local mhb=lhb._unique_item_data and lhb._unique_item_data._unique_relic_data
if not mhb then
return 0
end
local nhb=N.Items[lhb.item_id]or{}
local ohb,phb=V.types(khb.unit_id)
if nhb.main_damage_type and nhb.main_damage_type~=NQe[3059]and nhb.main_damage_type~=phb then
return 0
end
local qhb,rhb=0,0
for shb,thb in pairs(mhb._core_damage_type_buffs or{})do
if ohb[thb.damage_type]then
qhb=qhb+(tonumber(thb.mul)or 0)+(tonumber(thb.add_upg)or 0)*0.01+(tonumber(thb.pen)or 0)*0.001
rhb=rhb+(tonumber(thb.crit)or 0)
end
end
qhb=qhb+rhb*0.5
local uhb=V.rows(khb.unit_id)
local vhb=uhb and uhb[uhb.max]
local whb=(vhb and tonumber(vhb.cd)or 0)*V.mult(khb,NQe[2799])
for xhb,yhb in pairs(mhb._unique_relic_effects or{})do
local zhb=type(yhb.params)==NQe[2348]and yhb.params or{}
if yhb.id==NQe[3468]then
local Ahb=math.min(1,(tonumber(zhb.extra_damage)or 0)*whb/math.max(1,tonumber(zhb.time_interval)or 40))
local Bhb=V.DRONES and V.DRONES[khb.unit_id]
if Bhb and Bhb.late and whb>0 then
local Chb=1/whb
Ahb=Ahb*Chb/(Chb+(tonumber(Bhb.max)or 0)*(tonumber(Bhb.late.dmg)or 0)*(tonumber(Bhb.hits)or 1)/math.max(0.1,tonumber(Bhb.late.cd)or 4))
end
qhb=qhb+Ahb
elseif yhb.id==NQe[3469]then
qhb=qhb+(tonumber(zhb.dmg_buff)or 0)*0.25
elseif yhb.id==NQe[3470]then
qhb=qhb+(tonumber(zhb.dmg_buff)or 0)*rhb
elseif yhb.id==NQe[3471]then
if ohb.magic then
qhb=0
else
qhb=qhb+(tonumber(zhb.dmg_buff)or 0)*0.3
end
elseif yhb.id==NQe[3472]then
if ohb.water_damage then
qhb=qhb+0.05
end
elseif yhb.id==NQe[2500]then
local Dhb=tonumber(zhb.duration_buff)or tonumber(type(yhb.static_params)==NQe[2348]and yhb.static_params.duration_buff)or 2
local Ehb,Fhb=pcall(V.attackInfo,vhb and vhb.atk,vhb and vhb.range)
local Ghb,Hhb=Ehb and tonumber(Fhb.burn)or 0,Ehb and tonumber(Fhb.dot)or 0
if Ghb<=0 then
local Ihb,Jhb=pcall(pb.model,khb.unit_id,Ehb and Fhb or nil,vhb)
if Ihb and type(Jhb)==NQe[2348]and(tonumber(Jhb.burnDot)or 0)>0 then
Ghb,Hhb=Jhb.burnDot,Hhb+(tonumber(Jhb.dot)or 0)
end
end
qhb=qhb+Ghb*math.max(0,Dhb-1)/(1+Hhb)
end
end
return qhb
end
function kb.relicPlan()
local Khb=N.session()
if not Khb then
return nil
end
local Lhb=Khb.inventory and Khb.inventory.inventory_profile_data or{}
local Mhb={}
for Nhb,Ohb in ipairs(Lhb.unique_items or{})do
if type(Ohb)==NQe[2348]and Ohb.uuid and(N.Items[Ohb.item_id]or{}).item_group==NQe[3401]then
table.insert(Mhb,Ohb)
end
end
local Phb={}
for Qhb,Rhb in ipairs(V.equipped())do
local Shb=Rhb.data and Rhb.data.rarity
if not V.isFarm(Rhb.id)and(Shb==NQe[2938]or Shb==NQe[2939]or Shb==NQe[3466]or Shb==NQe[3473])then
local Thb=kb.share(Rhb.id)
if not P.str.share[Rhb.id]then
Thb=math.min(Thb,0.15)
end
local Uhb={}
for Vhb,Whb in ipairs(Mhb)do
local Xhb=kb.relicWorth(Rhb.u,Whb)*Thb*100
if Xhb>0.01 then
table.insert(Uhb,{it=Whb,w=Xhb})
end
end
table.sort(Uhb,function(Yhb,Zhb)
if Yhb.w~=Zhb.w then
return Yhb.w>Zhb.w
end
return Yhb.it.uuid<Zhb.it.uuid
end)
local aib,bib={},{}
for cib,dib in ipairs(Uhb)do
local eib=bib[dib.it.item_id]or 0
if#aib<6 and eib<((N.Items[dib.it.item_id]or{}).unique_equip and 1 or 2)then
bib[dib.it.item_id]=eib+1
table.insert(aib,dib)
end
end
if Rhb.u._equipped_relic then
local fib=false
for gib,hib in ipairs(aib)do
if hib.it.uuid==Rhb.u._equipped_relic then
fib=true
end
end
local iib=not fib and Khb.inventory:get_item_by_uuid(Rhb.u._equipped_relic)
if iib then
table.insert(aib,{it=iib,w=kb.relicWorth(Rhb.u,iib)*Thb*100})
end
end
table.insert(Phb,{e=Rhb,share=Thb,opts=aib})
end
end
local jib,kib={},-1
local lib,mib,nib={},{},{}
local function oib(pib,qib)
if pib> #Phb then
if qib>kib then
kib=qib
jib=table.clone(lib)
end
return
end
local rib=Phb[pib]
lib[rib.e.uuid]=nil
oib(pib+1,qib)
for sib,tib in ipairs(rib.opts)do
local uib=(N.Items[tib.it.item_id]or{}).unique_equip
if not mib[tib.it.uuid]and not(uib and nib[tib.it.item_id])then
mib[tib.it.uuid]=true
if uib then
nib[tib.it.item_id]=true
end
lib[rib.e.uuid]=tib.it.uuid
oib(pib+1,qib+tib.w+(tib.it.uuid==rib.e.u._equipped_relic and 0.01 or 0))
lib[rib.e.uuid]=nil
mib[tib.it.uuid]=nil
if uib then
nib[tib.it.item_id]=nil
end
end
end
end
oib(1,0)
local vib,wib=0,{}
for xib,yib in ipairs(Phb)do
local zib=yib.e.u._equipped_relic and Khb.inventory:get_item_by_uuid(yib.e.u._equipped_relic)
local Aib=zib and kb.relicWorth(yib.e.u,zib)*yib.share*100 or 0
vib=vib+Aib
local Bib=jib[yib.e.uuid]and Khb.inventory:get_item_by_uuid(jib[yib.e.uuid])
local Cib=Bib and kb.relicWorth(yib.e.u,Bib)*yib.share*100 or 0
table.insert(wib,string.format(NQe[3474],V.name(yib.e.id),zib and(N.Items[zib.item_id]or{}).name or NQe[2949],Aib,Bib and(N.Items[Bib.item_id]or{}).name or NQe[2949],Cib))
end
return jib,kib-vib,wib,Phb
end
