end
local kkb=math.min(9,tonumber(jkb.story_world_rank)or tonumber(ikb.rank)or 9)
local lkb=tonumber(jkb.story_level_rank)or 6
local mkb=(ikb.kind==NQe[2397]and 1.5 or 1)*(kkb>5 and 2 or 1)
local nkb=2.1564^(kkb-1)*(40+10*lkb)/mkb
if ikb.kind==NQe[2373]then
nkb=3*30*2.1564^(kkb-1)/mkb
end
