function kb.feedPlan(Ekb)
local Fkb=V.trait(Ekb)
local Gkb=Fkb==NQe[3491]and 1.5 or 1
local Hkb=math.max(0,kb.xpFor(Ekb.unit_id,kb.cap(Ekb))-(tonumber(Ekb.xp)or 0))
local Ikb,Jkb,Kkb={},0,0
for Lkb,Mkb in ipairs(kb.foodHeld())do
local Nkb=Mkb.xp*Gkb
local Okb=math.min(Mkb.n,math.floor((Hkb-Jkb)/math.max(1,Nkb)))
if Okb>0 then
Ikb[Mkb.id]=Okb
Jkb=Jkb+Okb*Nkb
Kkb=Kkb+Okb
end
end
return{feed=Ikb,planned=Jkb,n=Kkb}
end
function kb.run(Pkb)
local Qkb=N.session()
local Rkb=Qkb and Qkb.collection:get_unit_by_uuid(Pkb.uuid)
if not Rkb then
return
end
if Pkb.kind==NQe[3485]then
local Skb=kb.feedPlan(Rkb)
local Tkb,Ukb,Vkb=Skb.feed,Skb.planned,Skb.n
if Vkb==0 then
P.str.feedNote=Pkb.name..NQe[3492]
return
end
local Wkb,Xkb=tonumber(Rkb.xp)or 0,kb.level(Rkb)
local Ykb,Zkb=F.request(NQe[3485],NQe[3493],Pkb.uuid,Tkb)
local _kb=U.now()
while U.now()-_kb<4 and(tonumber((Qkb.collection:get_unit_by_uuid(Pkb.uuid)or Rkb).xp)or 0)<=Wkb do
task.wait(0.25)
end
local alb=Qkb.collection:get_unit_by_uuid(Pkb.uuid)or Rkb
local blb=(tonumber(alb.xp)or 0)-Wkb
if blb>0 then
local clb=kb.level(alb)
local dlb=clb>Xkb and string.format(NQe[3487],Xkb,clb)or string.format(NQe[3488],Xkb)
cb.add(string.format(NQe[3494],Vkb,Pkb.name),Vkb,NQe[3495],string.format(NQe[3496],U.fmt(blb),dlb))
kb.note(string.format(NQe[3497],Pkb.name,Vkb,U.fmt(blb),dlb,math.abs(blb-Ukb)>Ukb*0.1 and string.format(NQe[3498],U.fmt(Ukb))or NQe[1267]))
else
kb.note(string.format(NQe[3499],Pkb.name,tostring(Ykb and Zkb or NQe[2902])))
F.backoff(NQe[3485],600)
end
end
end
function kb.slotOf(elb)
local flb=N.session()
for glb,hlb in pairs(flb and flb.profile_data.collection.equipped_units or{})do
if hlb==elb then
return tonumber(glb)or glb
end
end
return nil
end
function kb.reequip()
local ilb=P.str.reequip
if not ilb then
return true
end
local jlb=N.session()
local klb=jlb and jlb.collection:get_unit_by_uuid(ilb.uuid)
if not klb then
P.str.reequip=nil
return true
end
for llb=1,3 do
if kb.slotOf(ilb.uuid)then
break
end
F.request(NQe[3500],NQe[3501],ilb.uuid)
local mlb=U.now()
while U.now()-mlb<3 and not kb.slotOf(ilb.uuid)do
task.wait(0.25)
end
end
W._sigAt=nil
if kb.slotOf(ilb.uuid)then
P.str.reequip=nil
F.saveSoon()
return true
end
F.log(1,NQe[3502],string.format(NQe[3503],V.name(klb.unit_id),tostring(ilb.slot)))
return false
end
kb.REMOTE={feed=NQe[3485]}
kb.WORK_MAX=300
function kb.nextAct(nlb)
local olb=os.time()
for plb,qlb in ipairs(nlb or{})do
local rlb=F.req.back[kb.REMOTE[qlb.kind]or NQe[1267]]
if not qlb.blocked and not(rlb and U.now()<rlb)and(tonumber(P.str.noWork[qlb.kind])or 0)<=olb and(tonumber(P.str.noWork[qlb.kind..NQe[2501]..tostring(qlb.uuid)])or 0)<=olb then
return qlb
end
end
end
function kb.workSig()
local slb=0
for tlb,ulb in ipairs(kb.foodHeld())do
slb=slb+ulb.n
end
return tostring(slb)
end
kb.FEED_STOP_GAIN=0.5
function kb.focusReady()
if not(O.autoEvolve and O.evolveUnit~=NQe[1267])then
return nil
end
pcall(hb.refresh)
for vlb,wlb in ipairs(P.goals or{})do
if wlb.pinned and wlb.uuid==O.evolveUnit and wlb.ready and(ab.evoBlocked[wlb.uuid]or 0)<os.time()then
local xlb={}
for ylb,zlb in ipairs(V.equipped())do
xlb[zlb.uuid]=true
end
if not ab.evoEats(wlb,xlb)then
return wlb
end
end
end
end
function kb.hasWork(Alb)
if not Alb then
local Blb=kb.focusReady()
if Blb then
return NQe[3504]..V.name(Blb.from)..NQe[3505],NQe[2456]
end
for Clb,Dlb in ipairs(P.goals or{})do
local Elb=Dlb.pinned and ab.evolveBuyPlan(Dlb)
if Elb then
return NQe[3506]..((N.Items[Elb.item]or{}).name or Elb.item)..NQe[3507]..V.name(Dlb.from)..NQe[3505],NQe[2456]
end
end
if ab.snipeWanted()then
return NQe[3508]..V.name(O.snipeUnit)..NQe[3509],NQe[3510]
end
if ab.snipeDue()then
return NQe[3511]..V.name(O.snipeUnit)..NQe[3512],NQe[3510]
end
if P.ownSwap then
return NQe[3513]..V.name(P.ownSwap.into)..NQe[3514],NQe[3515]
end
end
if not O.team or O.strDry then
return nil
end
kb.acts=kb.plan()
ab.last.teamPlan=U.now()
local Flb=kb.acts
if not Alb then
Flb={}
for Glb,Hlb in ipairs(kb.acts)do
if not(Hlb.kind==NQe[3485]and(tonumber(Hlb.gain)or 0)<kb.FEED_STOP_GAIN)then
table.insert(Flb,Hlb)
end
end
end
local Ilb=kb.nextAct(Flb)
if Ilb then
return Ilb.text,Ilb.kind
end
if O.teamRelics and(tonumber(P.str.noWork.relic)or 0)<=os.time()and(not Alb or not(O.autoTeam and O.play))then
local Jlb,Klb=kb.relicPlan()
if Klb and Klb>=(Alb and kb.relicBar()or kb.RELIC_STOP_GAIN)then
return string.format(NQe[3516],Klb),NQe[3517]
end
end
if not Alb and O.teamXp and O.teamBuyXp and O.goldShop and os.time()-(tonumber(P.str.shopAt)or 0)>21600 and kb.xpRoom()>0 and(tonumber(N.cur(NQe[2423]))or 0)>(O.xpGoldFloor or 100000)then
return NQe[3518],NQe[3519]
end
return nil
end
function kb.finishWork()
local Llb=U.now()
local Mlb=0
while F.alive and O.master and not P.holdLobby and not P.pauseAll and U.now()-Llb<kb.WORK_MAX do
local Nlb,Olb=kb.hasWork(true)
if not Nlb then
break
end
F.status(NQe[3520],NQe[3521]..tostring(Nlb))
if Olb==NQe[3517]then
local Plb,Qlb=pcall(kb.relicsApply,true)
if not(Plb and Qlb)then
P.str.noWork.relic=os.time()+1800
end
else
kb.tick()
end
Mlb=Mlb+1
task.wait(4)
end
if Mlb>0 then
F.log(1,kb.LOG,string.format(NQe[3522],Mlb,math.floor(U.now()-Llb)))
W._sigAt,W.lastScored=nil,nil
F.saveSoon()
end
end
function kb.tick()
if not O.team then
P.str.next=NQe[3523]
return
end
if P.str.reequip then
kb.reequip()
end
local Rlb
if ab.every(NQe[3524],60)or not P.str.acts then
Rlb=kb.plan()
else
Rlb=kb.acts
end
kb.acts=Rlb or kb.acts or{}
local Slb=kb.nextAct(kb.acts)
if not Slb then
local Tlb=kb.acts[1]
P.str.next=Tlb and(Tlb.text..NQe[3525]..tostring(Tlb.blocked))or NQe[3526]
return
end
if O.strDry then
P.str.next=NQe[3527]..Slb.text..NQe[3528]
if P.str.dryLast~=Slb.text then
P.str.dryLast=Slb.text
F.log(1,kb.LOG,NQe[3529]..Slb.text)
end
return
end
P.str.next=Slb.text
local Ulb=kb.workSig()
local Vlb,Wlb=pcall(kb.run,Slb)
if not Vlb then
F.log(1,NQe[2357],NQe[3530]..tostring(Wlb))
end
if kb.workSig()==Ulb then
P.str.noWork[Slb.kind..NQe[2501]..tostring(Slb.uuid)]=os.time()+1800
end
local Xlb=F.req.back[kb.REMOTE[Slb.kind]or NQe[1267]]
if Xlb and Xlb>U.now()then
P.str.noWork[Slb.kind]=os.time()+math.ceil(Xlb-U.now())
end
ab.last.teamPlan=nil
end
function kb.rows()
local Ylb=N.session()
local Zlb={}
if not Ylb then
return Zlb
end
for _lb,amb in ipairs(P.str.core or{})do
local bmb=Ylb.collection:get_unit_by_uuid(amb)
if bmb then
local cmb,dmb=V.trait(bmb)
local emb={string.format(NQe[3531],kb.level(bmb),kb.cap(bmb)),kb.traitName(cmb,dmb)}
if bmb.trait_stats then
table.insert(emb,(ab.statRanks(bmb):gsub(NQe[2739],NQe[3532])))
end
table.insert(emb,V.relicName(bmb)and(NQe[3533]..V.relicName(bmb))or NQe[3534])
if kb.lb(bmb)>=1 then
table.insert(emb,NQe[3535])
end
local fmb
for gmb,hmb in ipairs(P.str.acts or{})do
if hmb.uuid==amb then
fmb=hmb
break
end
end
if fmb then
table.insert(emb,NQe[3536]..(fmb.text:gsub(NQe[3537],string.upper))..(fmb.blocked and(NQe[3538]..fmb.blocked..NQe[3029])or NQe[1267]))
end
table.insert(Zlb,{name=V.name(bmb.unit_id),text=table.concat(emb,NQe[2739])})
end
end
return Zlb
end
function kb.text()
if not O.team then
return NQe[3539]
end
local imb={P.str.next or NQe[3540]}
if P.str.relicNote then
table.insert(imb,NQe[3541]..P.str.relicNote)
end
for jmb=1,math.min(4,#(P.str.log or{}))do
table.insert(imb,os.date(NQe[3542],P.str.log[jmb].at)..NQe[2359]..P.str.log[jmb].msg)
end
return table.concat(imb,NQe[2363])
end
ab.last={}
ab.hatched={}
function ab.evolve(kmb,lmb)
local mmb=N.session()
local nmb=mmb.collection:get_unit_by_uuid(kmb.uuid)
if not nmb then
return false,NQe[3543]
end
local omb,pmb=0,{}
for qmb,rmb in pairs(mmb.profile_data.collection.owned_units)do
if rmb.unit_id==kmb.to then
omb=omb+1
pmb[qmb]=true
end
end
local smb,tmb=F.request(NQe[2456],NQe[3544],kmb.uuid)
task.wait(2)
local umb=mmb.collection:get_unit_by_uuid(kmb.uuid)
local vmb=0
for wmb,xmb in pairs(mmb.profile_data.collection.owned_units)do
if xmb.unit_id==kmb.to then
vmb=vmb+1
if not pmb[wmb]then
if O.fuseXpUnit==kmb.uuid then
O.fuseXpUnit,O.fuseXpId=wmb,kmb.to
F.saveSoon()
end
end
end
end
if vmb>omb then
local ymb={}
for zmb,Amb in ipairs(kmb.items or{})do
table.insert(ymb,string.format(NQe[3545],(N.Items[Amb.id]or{}).name or Amb.id,Amb.amount))
end
for Bmb,Cmb in ipairs(kmb.eats or{})do
table.insert(ymb,string.format(NQe[3546],Cmb.amount,V.name(Cmb.id)))
end
local Dmb=string.format(NQe[3547],V.name(kmb.from),V.name(kmb.to),U.fmt(kmb.scoreFrom or 0),U.fmt(kmb.scoreTo or 0))
cb.add(NQe[3548]..Dmb,1,NQe[3549],(lmb or NQe[3550])..(#ymb>0 and(NQe[3551]..table.concat(ymb,NQe[2472]))or NQe[1267]))
F.log(1,NQe[3552],Dmb..NQe[3553]..(lmb or NQe[3550])..(#ymb>0 and(NQe[3551]..table.concat(ymb,NQe[2472]))or NQe[1267]))
W._sigAt=nil
pcall(hb.refresh)
return true,V.name(kmb.to)..NQe[3554]
end
F.log(1,NQe[3552],NQe[3555]..V.name(kmb.from)..NQe[3086]..tostring(tmb)..NQe[3556]..tostring(umb and umb.unit_id))
return false,NQe[3557]..tostring(tmb)..NQe[3029]
end
ab.evoBlocked={}
function ab.evoEats(Emb,Fmb)
local Gmb=N.session()
local Hmb,Imb=pcall(V.score,Gmb.collection:get_unit_by_uuid(Emb.uuid))
for Jmb,Kmb in ipairs(Emb.eats or{})do
for Lmb,Mmb in ipairs(hb.copies(Kmb.id,Kmb.shiny,Emb.uuid))do
local Nmb=Gmb.collection:get_unit_by_uuid(Mmb.uuid)or Mmb
local Omb,Pmb=pcall(V.score,Nmb)
if Fmb[Mmb.uuid]or V.trait(Nmb)or(Hmb and Omb and Pmb>=Imb)then
return string.format(NQe[3558],V.name(Kmb.id))
end
end
end
end
ab.pickNote={}
function ab.pickDone(Qmb,Rmb,Smb,Tmb)
O[Qmb]=false
pcall(function()
nb.UI[Qmb].Set(false,true)
end)
ab.pickNote[Qmb]=Smb
F.log(1,NQe[2872],Rmb..NQe[2706]..Smb)
if F.notify then
F.notify(Rmb,Smb,Tmb or NQe[3332])
end
F.saveSoon()
end
function ab.focusNextUp()
if O.focusNext==NQe[1267]or nb.focusNow()~=NQe[1267]then
return
end
local Umb=O.focusNext
local Vmb=N.session()
local Wmb,Xmb
for Ymb,Zmb in pairs(Vmb.profile_data.collection.owned_units)do
if Zmb.unit_id==Umb and(not Wmb or(tonumber(Zmb.xp)or 0)>Xmb)then
Wmb,Xmb=Ymb,tonumber(Zmb.xp)or 0
end
end
if not Wmb then
O.focusNext=NQe[1267]
F.log(1,NQe[2872],NQe[3559]..V.name(Umb)..NQe[3560])
return F.saveSoon()
end
O.focusDone=O.evolveUnit
F.log(1,NQe[2872],NQe[3561]..V.name(Umb))
ab.setFocus(Wmb)
nb.focusSig=nil
if F.notify then
F.notify(NQe[3562],NQe[3563]..V.name(Umb),NQe[3332])
end
end
function ab.evolveBuyPlan(_mb)
if not(O.autoEvolve and _mb and _mb.pinned and not _mb.ready and _mb.uuid==O.evolveUnit)then
return nil
end
for anb,bnb in ipairs(_mb.plans or{})do
if bnb.eventShop and(tonumber(bnb.cost)or 0)>0 and bnb.currency and hb.have(bnb.item)<(tonumber(bnb.need)or 1)and(tonumber(N.cur(bnb.currency))or 0)>=bnb.cost then
return bnb
end
if bnb.craft and bnb.ready and hb.have(bnb.item)<(tonumber(bnb.need)or 1)and(tonumber(N.cur(NQe[2423]))or 0)>=(tonumber(bnb.gold)or 0)then
return bnb
end
end
return nil
end
ab.CRAFT_EVOLVE_UI=NQe[3564]
function ab.evolveBuy(cnb)
local dnb=ab.evolveBuyPlan(cnb)
if not dnb or F.where~=NQe[2428]then
return false
end
if F.req.back.evobuy and U.now()<F.req.back.evobuy then
return false
end
local enb=(N.Items[dnb.item]or{}).name or dnb.item
local fnb=hb.have(dnb.item)
if dnb.craft then
local gnb,hnb=F.request(NQe[3565],NQe[3451],dnb.item,ab.CRAFT_EVOLVE_UI)
local inb=U.now()
while U.now()-inb<4 and hb.have(dnb.item)<=fnb do
task.wait(0.25)
end
if hb.have(dnb.item)>fnb then
cb.add(enb,dnb.gold or 0,NQe[2423],NQe[3566]..V.name(cnb.from)..NQe[3567])
F.log(1,NQe[3552],string.format(NQe[3568],enb,U.fmt(dnb.gold or 0),V.name(cnb.from)))
if F.notify then
F.notify(NQe[3562],NQe[3569]..enb..NQe[3507]..V.name(cnb.from),NQe[3332])
end
pcall(hb.refresh)
return true
end
F.log(1,NQe[3552],string.format(NQe[3570],enb,tostring(gnb and hnb or NQe[2902])))
F.backoff(NQe[3565],900)
return false
end
local jnb,knb=F.request(NQe[3565],NQe[2977],dnb.item,NQe[2371],NQe[2978],NQe[2802])
local lnb=U.now()
while U.now()-lnb<4 and hb.have(dnb.item)<=fnb do
task.wait(0.25)
end
if hb.have(dnb.item)>fnb then
cb.add(enb,dnb.cost,tostring(dnb.currency),NQe[3571]..V.name(cnb.from)..NQe[3567])
if F.notify then
F.notify(NQe[3562],NQe[3330]..enb..NQe[3507]..V.name(cnb.from),NQe[3332])
end
pcall(hb.refresh)
return true
end
F.log(1,NQe[3333],string.format(NQe[3572],enb,tostring(jnb and knb or NQe[2902])))
F.backoff(NQe[3565],900)
return false
end
function ab.autoEvolve()
if not O.autoEvolve or O.evolveUnit==NQe[1267]then
return
end
local mnb=N.session()
if not(mnb and mnb.collection:get_unit_by_uuid(O.evolveUnit))then
return ab.pickDone(NQe[3573],NQe[3562],NQe[3574],NQe[3575])
end
local nnb
for onb,pnb in ipairs(P.goals or{})do
if pnb.pinned and pnb.uuid==O.evolveUnit then
nnb=pnb
break
end
end
if not nnb then
local qnb=mnb.collection:get_unit_by_uuid(O.evolveUnit)
local rnb=N.Units[qnb.unit_id]
if not(rnb and rnb.evolve and rnb.evolve.evolve_unit)then
ab.pickDone(NQe[3573],NQe[3562],V.name(qnb.unit_id)..NQe[3576],NQe[3575])
end
return
end
ab.pickNote.autoEvolve=nil
if not nnb.ready and ab.evolveBuy(nnb)then
for snb,tnb in ipairs(P.goals or{})do
if tnb.pinned and tnb.uuid==O.evolveUnit then
nnb=tnb
break
end
end
end
if not nnb.ready then
return
end
local unb={}
for vnb,wnb in ipairs(V.equipped())do
unb[wnb.uuid]=true
end
local xnb=ab.evoEats(nnb,unb)
if xnb then
ab.pickNote.autoEvolve=xnb
return
end
if(ab.evoBlocked[nnb.uuid]or 0)>=os.time()then
return
end
local ynb,znb=ab.evolve(nnb,NQe[3577])
if ynb then
ab.pickDone(NQe[3573],NQe[3562],znb)
else
ab.evoBlocked[nnb.uuid]=os.time()+3600
ab.pickNote.autoEvolve=znb
end
end
function ab.evolveText()
if O.evolveUnit==NQe[1267]then
return NQe[3578]
end
local Anb=ab.pickNote.autoEvolve and(NQe[2363]..ab.pickNote.autoEvolve)or NQe[1267]
if not O.autoEvolve then
return NQe[3579]..Anb
end
for Bnb,Cnb in ipairs(P.goals or{})do
if Cnb.pinned and Cnb.uuid==O.evolveUnit then
return Cnb.text..((W.onlyOn()and not Cnb.ready)and(NQe[3580]..W.onlyText()..NQe[3581])or NQe[1267])..Anb
end
end
return NQe[3582]..Anb
end
ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(Dnb)
local Enb=N.session()
local Fnb=ab.FUSE_RANK[O.fuseXpRarity]or 2
local Gnb={[Dnb.uuid]=true,[O.evolveUnit]=true}
for Hnb,Inb in ipairs(V.equipped())do
Gnb[Inb.uuid]=true
end
for Jnb,Knb in ipairs(P.savedTeam or{})do
Gnb[Knb]=true
end
for Lnb,Mnb in ipairs(P.train and P.train.on and P.train.on.base or{})do
Gnb[Mnb]=true
end
local Nnb={}
local function Onb(Pnb)
local Qnb=Pnb and N.Units[Pnb.unit_id]
local Rnb=Qnb and Qnb.evolve and(Pnb.shiny and Qnb.evolve.shiny or Qnb.evolve.normal)
for Snb,Tnb in pairs(type(Rnb)==NQe[2348]and type(Rnb.unit_requirement)==NQe[2348]and Rnb.unit_requirement or{})do
if type(Tnb)==NQe[2348]and Tnb.unit_id then
Nnb[Tnb.unit_id]=math.max(Nnb[Tnb.unit_id]or 0,tonumber(Tnb.amount)or 1)
end
end
end
pcall(Onb,Dnb)
pcall(function()
Onb(Enb.collection:get_unit_by_uuid(O.evolveUnit))
end)
local Unb,Vnb={},0
for Wnb,Xnb in pairs(Enb.profile_data.collection.owned_units)do
local Ynb=N.Units[Xnb.unit_id]
local Znb=Ynb and ab.FUSE_RANK[Ynb.rarity]
if Znb and Znb<=Fnb and not Gnb[Wnb]and(Nnb[Xnb.unit_id]or 0)>0 then
Nnb[Xnb.unit_id]=Nnb[Xnb.unit_id]-1
Znb=nil
end
if Znb and Znb<=Fnb and not Gnb[Wnb]then
local _nb=Enb.collection:get_unit_by_uuid(Wnb)or Xnb
if not(Xnb._locked or _nb._locked)and not(Xnb._equipped_relic or _nb._equipped_relic)then
local aob,bob=pcall(N.USC.calculate_xp_gain_from_fuse,Dnb,{_nb},Enb)
bob=aob and tonumber(bob)or 0
if bob>0 then
table.insert(Unb,{uuid=Wnb,id=Xnb.unit_id,xp=bob,rarity=Ynb.rarity})
Vnb=Vnb+bob
end
end
end
end
table.sort(Unb,function(cob,dob)
if cob.xp~=dob.xp then
return cob.xp<dob.xp
end
return cob.uuid<dob.uuid
end)
local eob=math.max(0,kb.xpFor(Dnb.unit_id,kb.cap(Dnb))-(tonumber(Dnb.xp)or 0))
local fob,gob={},0
for hob,iob in ipairs(Unb)do
if gob>=eob then
break
end
table.insert(fob,iob)
gob=gob+iob.xp
end
return fob,gob,eob,Vnb
end
function ab.fuseXpTarget(kob)
local lob=kob and kob.collection:get_unit_by_uuid(O.fuseXpUnit)
if lob then
if O.fuseXpId~=lob.unit_id then
O.fuseXpId=lob.unit_id
F.saveSoon()
end
return lob
end
