local Bsb=gb.run(hsb,Asb,{hpMul=bsb,train=Wrb.uuid})
if(osb and W.infTier(Bsb.wave)>=psb)or(not osb and Bsb.won)then
local Csb=gb.run(hsb,Asb,{hpMul=1,train=Wrb.uuid})
local Dsb=(Csb.tk or 0)/math.max(0.5,Csb.t/60)
if(Csb.won or osb)and(not xsb or Dsb>math.max(xsb.rate*1.5,xsb.rate+1))then
xsb={out=isb[qsb[ysb].i].unit_id,r=Csb,rate=Dsb,trial=zsb}
end
end
end
esb.ownMin=nsb.t/60
if not xsb then
