esb.ok=true
end
end
esb.pending=nil
F.log(1,NQe[3675],string.format(NQe[3676],Vrb.label,V.name(Wrb.id),esb.out and(NQe[3677]..V.name(esb.out))or NQe[1267],esb.ok and string.format(NQe[3678],math.floor((ib.perRun(Vrb.key,Wrb.id)or 0)+0.5),Wrb.what,esb.minutes,esb.ownMin)or tostring(esb.why)))
F.saveSoon()
