if FHb and GHb then
return false
end
local HHb=type(P.unitLab)==NQe[2348]and P.unitLab or{}
if HHb.pauseKey==EHb.key and os.time()<(tonumber(HHb.pauseUntil)or 0)then
return false
end
local IHb=W.rec(EHb.key)
local JHb,KHb=tonumber(IHb.runs)or 0,tonumber(IHb.wins)or 0
if EHb.kind==NQe[2373]then
local LHb,MHb=pcall(W.infDaily,N.prof(),EHb.level,W.infReach(EHb.key))
