RHb[THb.id]=true
end
local UHb,VHb,WHb
for XHb,YHb in pairs(PHb.profile_data.collection.owned_units)do
local ZHb=YHb.unit_id
if not RHb[XHb]and not RHb[ZHb]and N.Units[ZHb]and not V.isFarm(ZHb)and not V.allyBuff(ZHb)and os.time()-(tonumber(OHb.tried[ZHb])or 0)>ab.LAB.AGAIN and(tonumber(type(OHb.blank)==NQe[2348]and OHb.blank[ZHb])or 0)<ab.LAB.BLANKS then
local _Hb=ab.unitEvidence(ZHb)
if _Hb<ab.LAB.MIN_EVIDENCE then
local aIb=PHb.collection:get_unit_by_uuid(XHb)or YHb
local bIb=kb.score(aIb)
if bIb>0 and(not UHb or _Hb<VHb or(_Hb==VHb and bIb>WHb))then
UHb,VHb,WHb={uuid=XHb,id=ZHb,u=aIb},_Hb,bIb
end
end
end
end
if not UHb then
return
end
local cIb,dIb
for eIb,fIb in ipairs(QHb)do
if not V.isFarm(fIb.id)and not V.allyBuff(fIb.id)and fIb.uuid~=O.evolveUnit then
local gIb=kb.score(fIb.u)
if not cIb or gIb<dIb then
cIb,dIb=fIb,gIb
end
end
end
if not cIb then
return
end
OHb.tried[UHb.id]=os.time()
local hIb=0
for iIb in pairs(OHb.tried)do
hIb=hIb+1
if hIb>300 then
OHb.tried[iIb]=nil
end
end
local jIb,kIb=gb.levelFor(NHb)
if not jIb then
