end
local lIb=gb.info(jIb,NHb.key,kIb,NHb.mod or W.ldMod(jIb)or W.levelMod(NHb.level))
local mIb={}
for nIb,oIb in ipairs(QHb)do
table.insert(mIb,oIb.uuid==cIb.uuid and UHb.u or oIb.u)
end
local pIb,qIb=pcall(gb.run,lIb,gb.teamFrom(mIb,lIb.map),{hpMul=1.1})
local rIb=pIb and type(qIb)==NQe[2348]and(qIb.won or(lIb.infinite and(tonumber(qIb.wave)or 0)>=0.8*W.infReach(NHb.key)))
if not rIb then
F.log(2,NQe[4027],string.format(NQe[4028],V.name(UHb.id),NHb.label))
return
end
local sIb={}
for tIb,uIb in ipairs(QHb)do
table.insert(sIb,uIb.uuid==cIb.uuid and UHb.uuid or uIb.uuid)
end
if ab.equipTeam(sIb,NQe[4029]..V.name(UHb.id))then
OHb.now={id=UHb.id,out=cIb.id,key=NHb.key,at=os.time(),ev=VHb}
F.log(1,NQe[4027],string.format(NQe[4030],V.name(UHb.id),V.name(cIb.id),NHb.label,VHb))
F.saveNow()
end
