function eb.upgradeGain(CNb,DNb,ENb,FNb,GNb,HNb)
local INb,JNb=DNb[ENb],DNb[ENb+1]
local KNb=(INb.cd>0 and INb.damage/INb.cd or 0)
local LNb=(JNb.cd>0 and JNb.damage/JNb.cd or 0)*V.aoe(JNb.atk,JNb.range)/math.max(0.3,V.aoe(INb.atk,INb.range))
local MNb=KNb>0 and CNb*(LNb/KNb-1)or(HNb or 0)
local NNb=DNb[ENb+2]
if NNb and ENb+1<DNb.max and NNb.cd>0 and JNb.cd>0 and KNb>0 then
local ONb=CNb*((NNb.damage/NNb.cd)/KNb-1)
local PNb=FNb+NNb.cost*GNb
if ONb/PNb>MNb/FNb then
MNb=MNb+(ONb/PNb*FNb-MNb)*0.5
end
end
local QNb=(JNb.range or 0)>(INb.range or 0)and(1+((JNb.range-INb.range)/math.max(1,INb.range)))or 1
return math.max(0,MNb)*QNb
end
function eb.dpsFor(RNb,SNb)
if SNb<=0 then
return 0
end
local TNb={}
for UNb,VNb in ipairs(RNb)do
if not VNb.farm and not VNb.grif and VNb.gain>0 then
table.insert(TNb,VNb)
end
end
table.sort(TNb,function(WNb,XNb)
return WNb.gain/WNb.cost>XNb.gain/XNb.cost
end)
local YNb,ZNb=0,0
for _Nb,aOb in ipairs(TNb)do
if SNb<=0 then
break
end
ZNb=aOb.gain/aOb.cost
local bOb=math.min(1,SNb/aOb.cost)
YNb=YNb+aOb.gain*bOb
SNb=SNb-aOb.cost*bOb
end
return YNb+math.max(0,SNb)*ZNb*0.7
end
function eb.shieldDps(cOb,dOb,eOb,fOb,gOb,hOb,iOb)
if(fOb or 0)<=0 or(cOb or 0)<=0 or(gOb or 0)<=0 then
return cOb or 0
end
dOb,eOb,hOb=math.max(0.3,dOb or 2),math.max(1,eOb or 1),hOb or 1
local jOb=cOb*hOb*dOb/eOb
return gOb*eOb/((fOb/math.max(1,iOb or 1)+math.max(1,gOb/jOb))*dOb)/hOb
end
function eb.shieldGain(kOb,lOb,mOb,nOb,oOb,pOb,qOb,rOb)
local sOb,tOb=V.attackInfo(lOb.atk,lOb.range),V.attackInfo(nOb.atk,nOb.range)
local uOb=eb.shieldDps(kOb,(tonumber(lOb.cd)or 2)*(qOb or 1),sOb.n,oOb,pOb,rOb,sOb.hits)
local vOb=eb.shieldDps(mOb,(tonumber(nOb.cd)or 2)*(qOb or 1),tOb.n,oOb,pOb,rOb,tOb.hits)
local wOb=math.max(0,((tonumber(nOb.range)or 0)-(tonumber(lOb.range)or 0))/math.max(1,tonumber(lOb.range)or 1))
return math.max(0,vOb-uOb)+uOb*wOb
end
function eb.shieldWork(xOb,yOb,zOb,AOb,BOb,COb,DOb,EOb,FOb)
if(AOb or 0)<=0 then
return 0
end
local GOb=3*AOb*(BOb or 1)/math.max(1,COb or 20)
if(zOb or 0)>=GOb then
return 0
end
return math.max(1,xOb or 1)*math.max(1,FOb or 1)/math.max(0.3,yOb or 2)*math.min(DOb or 0,EOb or 0)
end
function eb.holdGain(HOb,IOb,JOb,KOb)
if not HOb or(IOb or 0)<=0 then
return 0
end
local LOb,MOb=tonumber(HOb.stun)or 0,tonumber(HOb.slowTime)or 0
if LOb<=0 and MOb<=0 then
return 0
end
local NOb,OOb=LOb>0 and LOb or MOb,LOb>0 and 1 or(tonumber(HOb.slowPct)or 0.3)
local POb=OOb*NOb/(NOb+(tonumber(HOb.ccCd)or 8))
local QOb=POb/math.max(0.1,1-POb)
return IOb*QOb*U.clamp(JOb or 0.5,0,1)*math.min(1,(tonumber(HOb.n)or 1)/2)/(1+(KOb or 0))
end
function eb.bleedGain(ROb,SOb,TOb,UOb)
if(ROb or 0)<=0 then
return 0
end
local VOb=SOb or 0
for WOb,XOb in ipairs(TOb or{})do
VOb=math.max(VOb,(tonumber(XOb.hp)or 0)*0.5)
end
return ROb*VOb*(UOb and 0.5 or 1)
end
function eb.bleedShare(YOb,ZOb,_Ob,aPb)
if YOb<=0 or not ZOb then
return 0
end
if aPb then
return ZOb==0 and YOb or YOb/(ZOb+1)
end
return _Ob<ZOb and YOb/(ZOb-_Ob)or 0
end
function eb.keepsUp(bPb,cPb,dPb,ePb,fPb)
local gPb=bPb.coming
if not(gPb and#gPb>0 and bPb.waveSec)then
return true
end
local hPb=bPb.eff or 1
local iPb=bPb.money-dPb
local jPb=(bPb.teamDps or 0)*(bPb.shieldK or 1)+(ePb or 0)*hPb+eb.dpsFor(cPb,math.max(0,iPb))*hPb
local kPb=(bPb.farmNow or 0)+(fPb or 0)
local lPb=(bPb.roadSec or 130)*U.clamp(bPb.cover or 0.6,0.1,1)
local mPb=bPb.hpAlive or 0
for nPb,oPb in ipairs(gPb)do
mPb=math.max(0,mPb+oPb.hp-jPb*bPb.waveSec)
local pPb=jPb*lPb
if mPb>pPb then
return false,nPb,pPb/math.max(1,mPb)
end
if nPb< #gPb then
jPb=jPb+eb.dpsFor(cPb,(oPb.reward or 0)+kPb)*hPb*(0.85^nPb)
end
end
return true
end
eb.BOX_FROM=0.15
function eb.boxFrom(qPb)
local rPb=0
for sPb,tPb in ipairs(qPb)do
rPb=rPb+tPb.w
end
if rPb<=0 then
return nil
end
table.sort(qPb,function(uPb,vPb)
return uPb.p<vPb.p
end)
local wPb=0
for xPb,yPb in ipairs(qPb)do
wPb=wPb+yPb.w
if wPb>=rPb*eb.BOX_FROM then
return yPb.p
end
end
return nil
end
function eb.boxPressure(zPb,APb,BPb)
if not APb or APb<=0.05 or BPb<=APb+0.05 then
return zPb
end
return BPb*U.clamp((zPb-APb)/(BPb-APb),0,1)
end
function eb.decide(CPb,DPb)
local EPb=U.clamp(DPb.cover or 0.6,0.1,1)
local FPb=eb.boxPressure(DPb.pressure,DPb.boxFrom,EPb)
local GPb=math.max(O.clearSec,0.7*(DPb.roadSec or 50)*EPb)
local HPb=(DPb.clearSec or 0)>GPb
DPb.piling=DPb.piling and HPb
local IPb=DPb.attackers>0 and FPb<math.min(O.safeReach,EPb*0.75)and not DPb.piling and not HPb
local JPb=FPb>=math.min(O.dangerReach,EPb*0.9)or(DPb.piling and DPb.enemies>=18)
local KPb,LPb
for MPb,NPb in ipairs(CPb)do
if NPb.farm then
if O.farmUnits and NPb.gain>0 then
NPb.payback=NPb.cost/NPb.gain
if DPb.left-1>=NPb.payback+(DPb.farmSpare or O.farmSpare)and(not KPb or NPb.payback<KPb.payback)then
KPb=NPb
end
end
else
NPb.ratio=NPb.gain/math.max(1,NPb.cost)
if not LPb or NPb.ratio>LPb.ratio then
LPb=NPb
end
end
end
if DPb.leak and DPb.attackers>0 then
local OPb
for PPb,QPb in ipairs(CPb)do
local RPb=not DPb.airLeak or(QPb.e and bb.cardAir(QPb.e.id))
if QPb.place and not QPb.farm and not QPb.idol and not QPb.grif and RPb and QPb.cost<=DPb.money and not(QPb.e and V.allyBuff(QPb.e.id))and(not OPb or QPb.gain>OPb.gain)then
OPb=QPb
end
end
if OPb then
return OPb,string.format(NQe[4174],math.floor(DPb.leak*100))
end
end
local SPb=DPb.future<DPb.wantLeft*1.1
local TPb,UPb,VPb=true,nil,nil
if KPb then
TPb,UPb,VPb=eb.keepsUp(DPb,CPb,KPb.cost,0,KPb.gain)
end
local WPb=DPb.coming and not eb.keepsUp(DPb,CPb,0,0,0)
local XPb=false
if bb.random and KPb and not JPb and DPb.attackers>=2 and KPb.payback<=DPb.left/3 then
local YPb=0
for ZPb,_Pb in ipairs(bb.mine or{})do
if V.isFarm(_Pb._stats.id.Value)then
YPb=YPb+1
end
end
XPb=not KPb.place or YPb<4
end
if WPb and DPb.attackers>0 then
JPb=true
end
if JPb and LPb and LPb.grif then
LPb=nil
for aQb,bQb in ipairs(CPb)do
if not bQb.farm and not bQb.grif and(not LPb or bQb.ratio>LPb.ratio)then
LPb=bQb
end
end
end
local cQb=math.max(1,DPb.incomeRate or 20)
local dQb=DPb.waveSec or 20
local function eQb(fQb,gQb,hQb)
local iQb=math.max(0,(fQb.cost-DPb.money)/cQb)
local jQb=fQb.gain*math.max(0,hQb-iQb)
if gQb then
local kQb=math.max(0,DPb.money-fQb.cost)
local lQb=iQb+math.max(0,(gQb.cost-kQb)/cQb)
jQb=jQb+gQb.gain*math.max(0,hQb-lQb)
end
return jQb
end
local mQb,nQb
if DPb.attackers==0 and LPb then
local oQb=4*dQb
