function gb.evaluate(ijc,jjc)
local kjc=gb.run(ijc,jjc,{hpMul=1})
local ljc={won=kjc.won,wave=kjc.wave,minutes=kjc.t/60,aliveAt=kjc.aliveAt,total=ijc.total,at=os.time()}
