elseif kjc.won then
local mjc=gb.run(ijc,jjc,{hpMul=1.3})
ljc.p=mjc.won and 0.92 or 0.7
ljc.margin=mjc.won and NQe[4293]or NQe[4294]
else
local njc=gb.run(ijc,jjc,{hpMul=0.75})
ljc.p=njc.won and 0.25 or 0.05
ljc.margin=njc.won and string.format(NQe[4295],kjc.wave)or string.format(NQe[4296],kjc.wave,ijc.total)
if not njc.won then
local ojc=gb.run(ijc,jjc,{hpMul=0.25})
if not ojc.won then
ljc.p,ljc.hopeless=0.005,true
ljc.margin=string.format(NQe[4297],kjc.wave,ijc.total)
end
end
end
return ljc
end
