function gb.styleP(pjc,qjc)
local rjc=tonumber(pjc and pjc.p)or 0
if rjc<0.5 then
return rjc
end
qjc=qjc or((pjc.zone or pjc.style==NQe[4232])and NQe[4232]or NQe[4298])
local sjc,tjc=pcall(db.hiveStyle,qjc)
if not(sjc and tjc)then
return rjc
end
local ujc=tonumber(tjc.predWin)or 0
local vjc=U.clamp((tonumber(tjc.predWinWon)or 0)/math.max(1,ujc),0,1)
local wjc=ujc/(ujc+gb.STYLE_RUNS)
return rjc*(1-wjc*(1-vjc))
end
function gb.levelTag(xjc)
if type(xjc)~=NQe[2348]then
return NQe[2599]
end
if xjc._gamemode==NQe[2398]or xjc._infinite_tower_floor then
return NQe[4299]..tostring(xjc._infinite_tower_floor or xjc.floor_num or NQe[2599])
end
return tostring(xjc.id or NQe[2599])..(mb.is(xjc.id)and(NQe[2795]..tostring(xjc.map))or NQe[1267])
end
function gb.trust(yjc,zjc)
local Ajc=yjc.cal or{}
if type(Ajc.alive)~=NQe[2348]or Ajc.teamSig~=gb.sig((function()
local Bjc={}
for Cjc,Djc in ipairs(zjc)do
table.insert(Bjc,Djc.u)
end
return Bjc
end)())then
return nil
end
if yjc.key==NQe[3082]and not Ajc.aliveLvl then
return nil
end
if Ajc.aliveLvl and yjc.ld and(yjc.ld.id or yjc.key==NQe[2994])and Ajc.aliveLvl~=gb.levelTag(yjc.ld)then
return nil
end
local Ejc=gb.run(yjc,zjc,{hpMul=1})
local Fjc,Gjc,Hjc=0,0,0
for Ijc=3,math.min(Ejc.wave,tonumber(Ajc.lastWave)or 99)do
local Jjc=tonumber(Ajc.alive[tostring(Ijc)])
local Kjc=Ejc.aliveAt[Ijc]
if Jjc and Kjc and Jjc>0 then
Fjc=Fjc+Jjc
Gjc=Gjc+Kjc
Hjc=Hjc+1
end
end
if Hjc<2 or Gjc<=0 then
return nil
end
local Ljc=Fjc/Gjc
return{ratio=Ljc,ok=Ljc>=0.75 and Ljc<=1.33,waves=Hjc}
end
gb.GROWN_LEVEL,gb.GROWN_MIN=50,6
function gb.grownKinds()
local Mjc=N.session()
local Njc,Ojc={},0
for Pjc,Qjc in pairs(Mjc.profile_data.collection.owned_units)do
local Rjc=Qjc.unit_id
if not Njc[Rjc]and N.Units[Rjc]and not V.isFarm(Rjc)and V.rows(Rjc)and not V.hidden(Rjc)then
local Sjc,Tjc=pcall(N.USC.calculate_level,Rjc,tonumber(Qjc.xp)or 0)
if Sjc and(tonumber(Tjc)or 0)>=gb.GROWN_LEVEL then
Njc[Rjc]=true
Ojc=Ojc+1
end
end
end
return Ojc
end
function gb.pool(Ujc,Vjc)
local Wjc=N.session()
local Xjc,Yjc={},{}
local Zjc=gb.grownKinds()>=gb.GROWN_MIN
for _jc,akc in pairs(Wjc.profile_data.collection.owned_units)do
local bkc=Wjc.collection:get_unit_by_uuid(akc.uuid)or akc
local ckc,dkc=pcall(N.USC.calculate_level,bkc.unit_id,tonumber(bkc.xp)or 0)
local ekc=V.isFarm(bkc.unit_id)or not Zjc or(ckc and(tonumber(dkc)or 0)>=gb.GROWN_LEVEL)
if N.Units[bkc.unit_id]and V.rows(bkc.unit_id)and not V.hidden(bkc.unit_id)and ekc then
local fkc=V.isFarm(bkc.unit_id)
local gkc,hkc=pcall(fkc and function()
return V.farm(bkc,V.rows(bkc.unit_id).max)
end or V.score,bkc,Ujc)
hkc=(gkc and hkc or 0)*(fkc and 1 or V.skinMul(bkc,Vjc and Vjc.skinSet)*V.eventMul(bkc,Vjc and Vjc.ld))
local ikc=fkc and Yjc or Xjc
if not ikc[bkc.unit_id]or hkc>ikc[bkc.unit_id].sc then
ikc[bkc.unit_id]={u=bkc,sc=hkc}
end
end
end
local jkc,kkc={},{}
for lkc,mkc in pairs(Xjc)do
table.insert(jkc,mkc)
end
for nkc,okc in pairs(Yjc)do
table.insert(kkc,okc)
end
table.sort(jkc,function(pkc,qkc)
return pkc.sc>qkc.sc
end)
table.sort(kkc,function(rkc,skc)
return rkc.sc>skc.sc
end)
local tkc={}
for ukc=1,math.min(10,#jkc)do
table.insert(tkc,jkc[ukc].u)
end
local vkc,wkc={},{}
for xkc=11,#jkc do
local ykc=V.rows(jkc[xkc].u.unit_id)
for zkc=0,ykc.max do
if ykc[zkc]and ykc[zkc].atk and V.attackInfo(ykc[zkc].atk,ykc[zkc].range).dot>0 then
table.insert(zkc==0 and vkc or wkc,jkc[xkc].u)
break
end
end
end
for Akc=1,math.min(4,#vkc)do
table.insert(tkc,vkc[Akc])
end
for Bkc=1,math.min(2,#wkc)do
table.insert(tkc,wkc[Bkc])
end
for Ckc=1,math.min(3,#kkc)do
table.insert(tkc,kkc[Ckc].u)
end
local Dkc={}
for Ekc=11,#jkc do
local Fkc=V.rows(jkc[Ekc].u.unit_id)[0]
local Gkc=Fkc and Fkc.atk and V.attackInfo(Fkc.atk,Fkc.range)
if Gkc and(Gkc.slowTime>0 or Gkc.stun>0)then
table.insert(Dkc,jkc[Ekc].u)
end
end
for Hkc=1,math.min(3,#Dkc)do
table.insert(tkc,Dkc[Hkc])
end
for Ikc=11,#jkc do
local Jkc=jkc[Ikc].u.unit_id
if V.allyBuff(Jkc)or V.BLESS.by[Jkc]or V.GALE[Jkc]then
table.insert(tkc,jkc[Ikc].u)
end
end
if Vjc and((Vjc.flyChance or 0)>0 or Vjc.mapFly or(Vjc.shield or 0)>0)then
local Kkc,Lkc={},{}
for Mkc=11,#jkc do
local Nkc=jkc[Mkc].u
local Okc=V.rows(Nkc.unit_id)[0]
if V.airFrom(Nkc.unit_id)==0 then
table.insert(Kkc,Nkc)
end
local Pkc,Qkc=tonumber(Okc and Okc.cd)or 0,tonumber((N.Units[Nkc.unit_id]or{}).cost)or 0
if Pkc>0 and Qkc>0 and V.range(Nkc,0)>=15 then
local Rkc=V.attackInfo(Okc.atk,Okc.range)
table.insert(Lkc,{u=Nkc,v=Rkc.n*Rkc.hits/Pkc/Qkc*math.min(6,V.cap(Nkc))})
end
end
table.sort(Lkc,function(Skc,Tkc)
return Skc.v>Tkc.v
end)
for Ukc=1,math.min(4,#Kkc)do
table.insert(tkc,Kkc[Ukc])
end
for Vkc=1,math.min(6,#Lkc)do
table.insert(tkc,Lkc[Vkc].u)
end
end
local Wkc,Xkc={},{}
for Ykc,Zkc in ipairs(tkc)do
if not Wkc[Zkc]then
Wkc[Zkc]=true
table.insert(Xkc,Zkc)
end
end
Xkc.rest={}
for _kc,alc in ipairs(jkc)do
if not Wkc[alc.u]then
table.insert(Xkc.rest,alc.u)
end
end
return Xkc
end
function gb.objective(blc)
if blc.kscore then
return(tonumber(blc.kills)or 0)+blc.wave*0.01
end
return(blc.won and 1000 or 0)+blc.wave*10-(blc.won and blc.t/60 or((blc.left or 1)*9-math.min(9,blc.t/60)))
end
gb.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function gb.cliff(clc,dlc,elc)
local flc
for glc,hlc in ipairs(gb.LADDER)do
flc=gb.run(clc,dlc,{hpMul=hlc,layout=elc})
if not flc.won then
return hlc,flc
end
end
return gb.LADDER[#gb.LADDER],flc
end
gb.TEAM_FASTER,gb.TEAM_FASTER_S=0.05,15
function gb.teamFaster(ilc,jlc,klc)
if ilc.infinite or ilc.timeLimit or type(klc)~=NQe[2348]or not klc.won or not tonumber(klc.minutes)then
return nil
end
local llc=gb.teamFrom(jlc,ilc.map)
local mlc=gb.run(ilc,llc,{hpMul=1})
if not(mlc and mlc.won)then
return nil
end
local nlc=gb.run(ilc,llc,{hpMul=1.3})
if not(nlc and nlc.won)then
return nil
end
local olc,plc=tonumber(klc.minutes)*60,tonumber(mlc.t)or math.huge
if plc<=olc*(1-gb.TEAM_FASTER)and olc-plc>=gb.TEAM_FASTER_S then
return{mine=olc,pick=plc}
end
return nil
end
function gb.exam(qlc,rlc)
local slc,tlc,ulc=gb.teamFrom(rlc,qlc.map),0,0
for vlc,wlc in ipairs(gb.LADDER)do
local xlc,ylc=0,0
for zlc,Alc in ipairs({0.92,1,1.08})do
local Blc=gb.run(qlc,slc,{hpMul=wlc*Alc})
if Blc.won then
xlc=xlc+1
end
ylc=ylc+Blc.wave
end
tlc,ulc=tlc+xlc,ylc/3
task.wait()
if xlc==0 then
break
end
end
return tlc,ulc
end
gb.ZONE_CLOSE,gb.ZONE_GAIN=1.3,20
function gb.zoneKey(Clc)
return tostring(Clc.key)..NQe[2501]..tostring(Clc.map)
end
function gb.zoneChoice(Dlc,Elc,Flc,Glc)
if O.killZone==false or Dlc.zone or bb.forcedWay(Dlc)or(Dlc.infinite and gb.unbound(Dlc.ld))then
return false
end
local Hlc=P.zoneRec[gb.zoneKey(Dlc)]
local Ilc=Hlc and(Hlc.style==NQe[4232]or(Hlc.style==nil and Hlc.zone==true))
if Hlc and Hlc.won then
return Ilc==true,Ilc and NQe[4300]or nil
end
if Hlc and Ilc then
return false,NQe[4301]
end
local Jlc=P.modes[Dlc.key]
local Klc=Jlc and tonumber(Jlc.streak)or 0
if not Hlc and Jlc and(tonumber(Jlc.wins)or 0)>0 and Klc==0 and Dlc.key~=NQe[3082]and Dlc.key~=NQe[3078]then
return false
end
local Llc=Hlc~=nil or Klc>0
local Mlc=Glc and Flc<=1 or(not Glc and Flc<=gb.ZONE_CLOSE)
if not(Llc or Mlc)then
return false
end
local Nlc=table.clone(Dlc)
Nlc.zone=true
local function Olc(Plc)
local Qlc=0
for Rlc,Slc in ipairs({0.92,1,1.08})do
Qlc=Qlc+gb.objective(gb.run(Plc,Elc,{hpMul=Flc*Slc}))
end
return Qlc/3
end
local Tlc=Olc(Nlc)-Olc(Dlc)
if Llc and Tlc> -gb.ZONE_GAIN then
return true,NQe[4302],Tlc
end
if Mlc and Tlc>gb.ZONE_GAIN then
return true,string.format(NQe[4303],Flc),Tlc
end
return false,nil,Tlc
end
function gb.strength(Ulc,Vlc)
local Wlc,Xlc,Ylc,Zlc,_lc=gb.teamFrom(Vlc,Ulc.map),0,0,0,0
for amc,bmc in ipairs(gb.LADDER)do
local cmc,dmc=0,0
for emc,fmc in ipairs({0.92,1,1.08})do
local gmc=gb.run(Ulc,Wlc,{hpMul=bmc*fmc})
if gmc.won then
cmc=cmc+1
end
dmc=dmc+gmc.wave
end
Xlc,_lc=Xlc+cmc,dmc/3
if bmc==1 then
Ylc,Zlc=cmc,dmc/3
