task.wait()
if cmc==0 then
break
end
end
return Xlc,Ylc,Zlc,_lc
end
function gb.lockIds()
local hmc={}
for imc,jmc in ipairs(type(O.teamLock)==NQe[2348]and O.teamLock or{})do
if type(jmc)==NQe[1253]then
hmc[jmc]=true
end
end
