end
function gb.lockTeam(kmc,lmc,mmc)
local nmc=table.clone(kmc)
local omc={}
for pmc,qmc in ipairs(nmc)do
omc[qmc.unit_id]=true
end
local rmc=N.session()
for smc in pairs(mmc)do
if not omc[smc]then
local tmc
for umc,vmc in ipairs({lmc or{},(type(lmc)==NQe[2348]and lmc.rest)or{}})do
for wmc,xmc in ipairs(vmc)do
if xmc.unit_id==smc then
tmc=xmc
break
end
end
if tmc then
break
end
end
if not tmc and rmc then
local ymc
for zmc,Amc in pairs(rmc.profile_data.collection.owned_units)do
if Amc.unit_id==smc then
local Bmc=rmc.collection:get_unit_by_uuid(Amc.uuid)or Amc
local Cmc,Dmc=pcall(V.score,Bmc)
Dmc=Cmc and tonumber(Dmc)or 0
if not ymc or Dmc>ymc then
tmc,ymc=Bmc,Dmc
end
end
end
end
if tmc then
local Emc
for Fmc,Gmc in ipairs(nmc)do
if not mmc[Gmc.unit_id]and V.sameGroup(Gmc.unit_id,smc)then
Emc=Fmc
end
end
if not Emc and#nmc<6 then
table.insert(nmc,tmc)
else
if not Emc then
local Hmc=0
for Imc,Jmc in ipairs(nmc)do
if V.isFarm(Jmc.unit_id)then
Hmc=Hmc+1
end
end
local Kmc
for Lmc,Mmc in ipairs(nmc)do
if not mmc[Mmc.unit_id]and not(V.isFarm(Mmc.unit_id)and Hmc<=1)then
local Nmc,Omc=pcall(V.score,Mmc)
Omc=V.isFarm(Mmc.unit_id)and math.huge or(Nmc and tonumber(Omc)or 0)
if not Kmc or Omc<Kmc then
Emc,Kmc=Lmc,Omc
end
end
end
end
if Emc then
nmc[Emc]=tmc
end
end
omc[smc]=true
end
end
end
return nmc
end
function gb.bestTeam(Pmc,Qmc,Rmc,Smc)
local Tmc=U.now()
Smc=Smc or 25
local Umc=table.clone(Qmc)
local Vmc=gb.lockIds()
if next(Vmc)then
local Wmc,Xmc=pcall(gb.lockTeam,Umc,Rmc,Vmc)
if Wmc and type(Xmc)==NQe[2348]then
Umc=Xmc
end
end
local function Ymc(Zmc)
return Zmc~=nil and Vmc[Zmc.unit_id]==true
end
local _mc,anc=gb.cliff(Pmc,gb.teamFrom(Umc,Pmc.map))
local function bnc(cnc)
local dnc=0
for enc,fnc in ipairs(cnc)do
if V.isFarm(fnc.unit_id)then
dnc=dnc+1
end
end
return dnc
end
local gnc=bnc(Rmc)>0
local function hnc(jnc)
local knc=0
for lnc,mnc in ipairs(jnc)do
if not V.isFarm(mnc.unit_id)and not V.allyBuff(mnc.unit_id)then
knc=knc+V.cap(mnc)
end
end
return knc
end
local nnc
while#Umc<6 do
local onc,pnc
local qnc=gnc and bnc(Umc)==0
for rnc,snc in ipairs(Rmc)do
local tnc=false
for unc,vnc in ipairs(Umc)do
if V.sameGroup(vnc.unit_id,snc.unit_id)then
tnc=true
end
end
if not tnc and(not qnc or V.isFarm(snc.unit_id))then
local wnc=table.clone(Umc)
table.insert(wnc,snc)
local xnc=gb.run(Pmc,gb.teamFrom(wnc,Pmc.map),{hpMul=_mc})
local ync=gb.objective(xnc)
if not pnc or ync>pnc then
onc,pnc,nnc=snc,ync,xnc
end
end
end
if not onc then
break
end
table.insert(Umc,onc)
end
if gnc and bnc(Umc)==0 then
local znc,Anc
for Bnc=1,#Umc do
for Cnc,Dnc in ipairs(Ymc(Umc[Bnc])and{}or Rmc)do
if V.isFarm(Dnc.unit_id)then
local Enc=table.clone(Umc)
Enc[Bnc]=Dnc
local Fnc=gb.run(Pmc,gb.teamFrom(Enc,Pmc.map),{hpMul=_mc})
local Gnc=gb.objective(Fnc)
if not Anc or Gnc>Anc then
znc,Anc,nnc=Enc,Gnc,Fnc
end
end
end
end
if znc then
Umc=znc
end
end
local function Hnc(Inc,Jnc)
local Knc=gb.teamFrom(Inc,Pmc.map)
return(gb.objective(Jnc)+gb.objective(gb.run(Pmc,Knc,{hpMul=_mc*0.92}))+gb.objective(gb.run(Pmc,Knc,{hpMul=_mc*1.08})))/3
end
local Lnc,Mnc=nnc or anc,Hnc(Umc,nnc or anc)
if type(Rmc.rest)==NQe[2348]and#Rmc.rest>0 then
local Nnc,Onc
for Pnc,Qnc in ipairs(Umc)do
if not V.isFarm(Qnc.unit_id)and not V.allyBuff(Qnc.unit_id)and not Ymc(Qnc)then
local Rnc,Snc=pcall(V.score,Qnc,Pmc.mod)
Snc=(Rnc and Snc or 0)*V.skinMul(Qnc,Pmc.skinSet)*V.eventMul(Qnc,Pmc.ld)
if not Onc or Snc<Onc then
Nnc,Onc=Pnc,Snc
end
end
end
if Nnc then
local Tnc,Unc={},U.now()
for Vnc,Wnc in ipairs(Rmc.rest)do
if U.now()-Unc>5 then
break
end
local Xnc=false
for Ync,Znc in ipairs(Umc)do
if V.sameGroup(Znc.unit_id,Wnc.unit_id)then
Xnc=true
end
end
if not Xnc then
local _nc=table.clone(Umc)
_nc[Nnc]=Wnc
table.insert(Tnc,{u=Wnc,o=gb.objective(gb.run(Pmc,gb.teamFrom(_nc,Pmc.map),{hpMul=_mc}))})
end
end
table.sort(Tnc,function(aoc,boc)
return aoc.o>boc.o
end)
Rmc=table.clone(Rmc)
for coc=1,math.min(4,#Tnc)do
table.insert(Rmc,1,Tnc[coc].u)
end
Tmc=Tmc+(U.now()-Unc)
end
end
for doc=1,2 do
local eoc=false
for foc=1,#Umc do
for goc,hoc in ipairs(Ymc(Umc[foc])and{}or Rmc)do
if U.now()-Tmc>Smc then
return Umc,Lnc,_mc,anc
end
local ioc=false
for joc,koc in ipairs(Umc)do
if joc~=foc and V.sameGroup(koc.unit_id,hoc.unit_id)then
ioc=true
end
end
if Umc[foc]and Umc[foc].unit_id==hoc.unit_id then
ioc=true
end
if not ioc then
local loc=table.clone(Umc)
loc[foc]=hoc
if(not gnc or bnc(loc)>0)and hnc(loc)>=math.min(8,hnc(Umc))then
local moc=gb.run(Pmc,gb.teamFrom(loc,Pmc.map),{hpMul=_mc})
local noc=gb.objective(moc)
if noc>Mnc+1 then
noc=Hnc(loc,moc)
if noc>Mnc+1 then
Umc,Mnc,Lnc,eoc=loc,noc,moc,true
end
end
end
end
end
end
if not eoc then
break
end
end
return Umc,Lnc,_mc,anc
end
function gb.evolutions()
