uoc=roc:get_number_of_owned_item(toc)
end)
return uoc
end
for voc,woc in pairs(ooc.profile_data.collection.owned_units)do
local xoc=N.Units[woc.unit_id]
if xoc and xoc.evolve and xoc.evolve.evolve_unit and not xoc.evolve.hide_from_ui and not qoc[woc.unit_id]and N.Units[xoc.evolve.evolve_unit]then
qoc[woc.unit_id]=true
local yoc=woc.shiny and xoc.evolve.shiny or xoc.evolve.normal
if yoc then
local zoc={}
for Aoc,Boc in pairs(yoc.item_requirement or{})do
if soc(Boc.item_id)<(Boc.amount or 1)then
table.insert(zoc,string.format(NQe[3387],(N.Items[Boc.item_id]or{}).name or Boc.item_id,soc(Boc.item_id),Boc.amount))
end
end
for Coc,Doc in pairs(yoc.unit_requirement or{})do
local Eoc=0
for Foc,Goc in pairs(ooc.profile_data.collection.owned_units)do
if Goc.unit_id==Doc.unit_id and(not Doc.shiny or Goc.shiny)then
Eoc=Eoc+1
end
end
if Eoc<(Doc.amount or 1)then
table.insert(zoc,string.format(NQe[3387],V.name(Doc.unit_id),Eoc,Doc.amount))
end
end
local Hoc=hb.killsShort(ooc.collection:get_unit_by_uuid(woc.uuid)or woc,yoc)
if Hoc then
table.insert(zoc,string.format(NQe[3380],Hoc.what,U.fmt(Hoc.have),U.fmt(Hoc.need)))
end
if#zoc<=1 then
local Ioc=ooc.collection:get_unit_by_uuid(woc.uuid)or woc
table.insert(poc,{u=Ioc,from=woc.unit_id,to=xoc.evolve.evolve_unit,missing=zoc,evolved={unit_id=xoc.evolve.evolve_unit,uuid=NQe[3375]..tostring(Ioc.uuid),xp=Ioc.xp,traits=Ioc.traits,trait_stats=Ioc.trait_stats,further_modifiers=Ioc.further_modifiers}})
end
end
end
end
return poc
end
