function bb.layoutAdd(X3c,Y3c,Z3c,_3c,a4c)
X3c.runs,X3c.wins=(tonumber(X3c.runs)or 0)+1,(tonumber(X3c.wins)or 0)+(Y3c and 1 or 0)
X3c.sec,X3c.wave=type(X3c.sec)==NQe[2348]and X3c.sec or{},type(X3c.wave)==NQe[2348]and X3c.wave or{}
if Y3c and tonumber(Z3c)then
table.insert(X3c.sec,math.floor(Z3c+0.5))
end
table.insert(X3c.wave,tonumber(_3c)or 0)
if tonumber(a4c)then
X3c.kills=type(X3c.kills)==NQe[2348]and X3c.kills or{}
table.insert(X3c.kills,math.floor(tonumber(a4c)))
while#X3c.kills>bb.LAYOUT_KEEP do
table.remove(X3c.kills,1)
end
end
while#X3c.sec>bb.LAYOUT_KEEP do
table.remove(X3c.sec,1)
end
while#X3c.wave>bb.LAYOUT_KEEP do
table.remove(X3c.wave,1)
end
end
function bb.layoutJudge(b4c,c4c,d4c,e4c,f4c)
f4c=f4c or NQe[4814]
local g4c,h4c=tonumber(b4c and b4c.runs)or 0,tonumber(c4c and c4c.runs)or 0
