local W4c=V4c.id.Value
if V4c:FindFirstChild(NQe[2616])and not V.isFarm(W4c)and not V.allyBuff(W4c)then
local X4c,Y4c=U.flat(U4c:GetPivot().Position),V4c.range.Value
if N4c(W4c)and not V.toggleOf(W4c)then
