end
end
if P4c<=O4c then
O4c,P4c=0.75,0.98
end
local a5c=(M4c or Q4c)+1
local b5c=({O4c,P4c,(O4c+P4c)/2,O4c-(P4c-O4c)/2})[a5c]
if not b5c then
