if type(gad)~=NQe[2348]or(tonumber(gad.n)or 0)<1 then
return 2,0,0
end
if(tonumber(gad.far)or 0)<0.5*(tonumber(fad.wave)or 0)then
return 3,tonumber(gad.best)or 0,tonumber(gad.far)or 0
end
return 1,tonumber(gad.best)or 0,tonumber(gad.far)or 0
end
local had,iad,jad,kad
for lad,mad in ipairs(cad)do
local nad,oad,qad=ead(mad)
if not had or nad<iad or(nad==iad and nad~=2 and(oad>jad or(oad==jad and qad>kad)))then
had,iad,jad,kad=lad,nad,oad,qad
end
end
if iad==2 and had==1 then
return nil
end
local rad=iad==1 and string.format(NQe[4839],kad)or iad==2 and NQe[4840]or string.format(NQe[4841],kad)
return had,rad
end
bb.DEF_APART=6
function bb.defTaken(sad,tad)
local uad=Vector3 .new(sad.X,0,sad.Z)
for vad,wad in ipairs(tad or{})do
if(Vector3 .new(wad.X,0,wad.Z)-uad).Magnitude<bb.DEF_APART then
return true
end
end
return false
end
function bb.defList()
local xad=N.session()
local yad=xad and xad.defense_units
N.Defenses=N.Defenses or N.data(NQe[1085])or{}
local zad={}
for Aad,Bad in pairs(type(yad)==NQe[2348]and yad or{})do
if type(Bad)==NQe[2348]and Bad.unit_uuid and not Bad.placed and(tonumber(Bad.d)or 0)>0 then
local Cad=N.Defenses[Bad.item_id]
local Dad=N.Items[Bad.item_id]
local Ead=type(Dad)==NQe[2348]and type(Dad.usage)==NQe[2348]and Dad.usage._defense_unit or Bad.item_id
local Fad=N.Units[Ead]
local Gad=bb.defKind(Cad,Fad)
if Gad and Gad~=NQe[4432]and not(Cad.night_only and not bb.ld._night)then
table.insert(zad,{slot=Aad,d=Bad,def=Cad,unit=Fad,kind=Gad,name=(type(Dad)==NQe[2348]and Dad.name)or Fad.name or Ead,range=tonumber(Fad.range)or 10})
end
end
end
local Had={aura=1,area=2,trap=3,barricade=4}
table.sort(zad,function(Iad,Jad)
if Had[Iad.kind]~=Had[Jad.kind]then
return Had[Iad.kind]<Had[Jad.kind]
end
return tostring(Iad.slot)<tostring(Jad.slot)
end)
return zad
end
function bb.roadProg(Kad,Lad)
local Mad,Nad
local Oad,Pad=Kad.X,Kad.Z
for Qad,Rad in ipairs(Lad or{})do
local Sad,Tad=Rad.pos.X-Oad,Rad.pos.Z-Pad
local Uad=Sad*Sad+Tad*Tad
if not Nad or Uad<Nad then
Mad,Nad=Rad,Uad
end
end
if not Mad then
return nil
end
return tonumber(Mad.prog),Mad.lane
end
function bb.defNote(Vad,Wad,Xad)
bb.defLog=bb.defLog or{}
local Yad,Zad=bb.roadProg(Wad,bb.samples)
local _ad,abd
for bbd,cbd in ipairs(bb.samples or{})do
local dbd=U.flat(cbd.pos)
for ebd,fbd in ipairs(Xad or{})do
if(fbd.p-dbd).Magnitude<=fbd.r then
local gbd=tonumber(cbd.prog)or 0
_ad,abd=math.min(_ad or gbd,gbd),math.max(abd or gbd,gbd)
break
end
end
end
table.insert(bb.defLog,{ref=Vad.d,slot=tostring(Vad.slot),id=tostring(Vad.d.item_id),k=Vad.kind,p=Yad and db.r3(Yad)or nil,lane=Zad,w=bb.wave(),a=_ad and db.r3(_ad)or nil,b=abd and db.r3(abd)or nil,n= #(Xad or{}),d0=tonumber(Vad.d.d)})
end
function bb.defReport()
if type(bb.defLog)~=NQe[2348]or#bb.defLog==0 then
return nil
end
local hbd={}
for ibd,jbd in ipairs(bb.defLog)do
local kbd=type(jbd.ref)==NQe[2348]and tonumber(jbd.ref.d)or nil
table.insert(hbd,{id=jbd.id,k=jbd.k,p=jbd.p,lane=jbd.lane,w=jbd.w,a=jbd.a,b=jbd.b,n=jbd.n,d0=jbd.d0,wear=(jbd.d0 and kbd and kbd<jbd.d0)and db.r3(jbd.d0-kbd)or nil})
if#hbd>=12 then
break
end
end
return hbd
end
bb.DEF_PREV_MAX=2*3600
function bb.defWearOf(lbd,mbd,nbd)
if type(lbd)~=NQe[2348]or type(lbd.defs)~=NQe[2348]or#lbd.defs==0 then
return nil
end
if nbd and lbd.at and nbd-lbd.at>bb.DEF_PREV_MAX then
return nil
end
local obd={level=lbd.level,map=lbd.map,style=lbd.style,won=lbd.won,players=lbd.players,at=lbd.at,defs={}}
for pbd,qbd in ipairs(lbd.defs)do
local rbd=type(mbd)==NQe[2348]and(mbd[qbd.slot]or mbd[tonumber(qbd.slot)])or nil
local sbd=type(rbd)==NQe[2348]and tostring(rbd.item_id)==qbd.id and tonumber(rbd.d)or nil
table.insert(obd.defs,{id=qbd.id,k=qbd.k,p=qbd.p,lane=qbd.lane,w=qbd.w,a=qbd.a,b=qbd.b,n=qbd.n,d0=qbd.d0,wear=(qbd.d0 and sbd and sbd<=qbd.d0)and db.r3(qbd.d0-sbd)or nil})
end
