function bb.defKeep(tbd)
if type(bb.defLog)~=NQe[2348]or#bb.defLog==0 then
return nil
end
local ubd={at=os.time(),level=tbd.level,map=tbd.map,style=tbd.sim and tbd.sim.style or nil,won=tbd.result and tbd.result.won or false,players=tbd.players,defs={}}
for vbd,wbd in ipairs(bb.defLog)do
table.insert(ubd.defs,{slot=wbd.slot,id=wbd.id,k=wbd.k,p=wbd.p,lane=wbd.lane,w=wbd.w,a=wbd.a,b=wbd.b,n=wbd.n,d0=wbd.d0})
if#ubd.defs>=12 then
break
