function bb.defTick()
if not O.defenses or bb.finished or not(bb.ld and(bb.ld._swordsmith or bb.ld._own_defenses))then
return
end
bb.defFail=bb.defFail or{}
bb.defUsed=bb.defUsed or{}
local xbd={}
for ybd,zbd in ipairs(bb.mine or{})do
local Abd=zbd:FindFirstChild(NQe[2420])
if Abd and Abd:FindFirstChild(NQe[2741])and Abd:FindFirstChild(NQe[2616])and not V.isFarm(Abd.id.Value)then
table.insert(xbd,{p=U.flat(zbd:GetPivot().Position),r=tonumber(Abd.range.Value)or 0})
end
end
if#xbd<2 and bb.wave()<3 then
return
end
if#xbd==0 then
return
end
local Bbd=bb.defList()
if#Bbd==0 and not bb.defWornSaid then
bb.defWornSaid=true
local Cbd,Dbd,Ebd=pcall(ab.defWorn)
if Cbd and Dbd>0 then
F.log(1,NQe[3430],string.format(NQe[4842],Dbd,Dbd==1 and NQe[4843]or NQe[4844],Ebd,hb.have(NQe[3417]),O.defRepair and NQe[4845]or NQe[4846]))
end
end
for Fbd,Gbd in ipairs(Bbd)do
local Hbd=Gbd.kind==NQe[4836]and#xbd<bb.BARR_TEAM and bb.wave()<bb.BARR_WAVE
if not Hbd and(bb.defFail[Gbd.slot]or 0)<3 and not(bb.defWait and bb.defWait[Gbd.slot]and#xbd<=bb.defWait[Gbd.slot])then
local Ibd=bb.defPick(Gbd.kind,Gbd.range,xbd,bb.cands or{},bb.samples or{},bb.cover)
local Jbd
for Kbd,Lbd in ipairs(Ibd)do
if bb.defTaken(Lbd,bb.defUsed)then
Jbd=nil
elseif Gbd.kind==NQe[4837]or Gbd.kind==NQe[4836]then
local Mbd=N.PC.raycast(Lbd+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
local Nbd,Obd=pcall(N.PC.is_valid_raycast_hit,Mbd and Mbd.Instance,Gbd.unit)
Jbd=Mbd and Nbd and Obd and Mbd.Position or nil
else
Jbd=bb.valid(Lbd,Gbd.unit)
end
if Jbd then
break
end
end
if not Jbd then
bb.defWait=bb.defWait or{}
if not bb.defWait[Gbd.slot]then
F.log(1,NQe[3430],string.format(NQe[4847],Gbd.name))
end
bb.defWait[Gbd.slot]= #xbd
else
local Pbd,Qbd=F.request(NQe[4848],NQe[4100],Gbd.d.unit_uuid,N.Util.CFramePLV(Jbd,bb.lookAt(Jbd)))
table.insert(bb.defUsed,U.flat(Jbd))
if Pbd and Qbd then
Gbd.d.placed=true
pcall(bb.defNote,Gbd,Jbd,xbd)
local Rbd=0
for Sbd,Tbd in ipairs(xbd)do
if(Tbd.p-U.flat(Jbd)).Magnitude<=Gbd.range then
Rbd=Rbd+1
end
end
F.log(1,NQe[3430],string.format(NQe[4849],Gbd.name,bb.spotKey(Jbd),Gbd.kind==NQe[2548]and string.format(NQe[4850],Rbd,#xbd)or(Gbd.kind==NQe[4838]and string.format(NQe[4851],bb.cover(Jbd,Gbd.range))or(Gbd.kind==NQe[4837]and NQe[4852]or NQe[4853]))))
else
bb.defFail[Gbd.slot]=(bb.defFail[Gbd.slot]or 0)+1
if bb.defFail[Gbd.slot]>=3 then
F.log(1,NQe[3430],string.format(NQe[4854],Gbd.name,tostring(Qbd)))
end
end
end
return
end
end
end
function bb.unplacedWhy(Ubd,Vbd)
if Vbd.farm and not Vbd.farmUnits then
return NQe[4855]
end
if(Vbd.noSpot or 0)>=3 then
return NQe[4856]
end
if(Vbd.noSpot or 0)>=1 then
return string.format(NQe[4857],Vbd.noSpot,Vbd.noSpot==1 and NQe[1267]or NQe[2194])
end
if Vbd.cost>0 and Vbd.money<Vbd.cost and Vbd.cost>Vbd.spent*0.5 then
return string.format(NQe[4858],U.fmt(Vbd.cost),U.fmt(Vbd.money))
end
return string.format(NQe[4859],Vbd.wave)
end
function bb.unplacedLine(Wbd)
if bb.joinedMid or bb.random or bb.trialId then
return nil
end
local Xbd={}
for Ybd,Zbd in ipairs(bb.mine or{})do
local _bd=Zbd:FindFirstChild(NQe[2420])
if _bd and _bd:FindFirstChild(NQe[2741])then
Xbd[_bd.id.Value]=true
end
end
local acd={}
for bcd,ccd in ipairs(V.equipped())do
if not(bb.placedAt and bb.placedAt[ccd.uuid])and not Xbd[ccd.id]then
local dcd=bb.unplacedWhy(ccd,{farm=V.isFarm(ccd.id),farmUnits=O.farmUnits==true,noSpot=bb.noSpot and bb.noSpot[ccd.uuid]or 0,cost=tonumber(ccd.data and ccd.data.cost)or 0,money=bb.money(),spent=tonumber(bb.spent)or 0,wave=bb.wave()})
table.insert(acd,string.format(NQe[4478],V.name(ccd.id),dcd))
end
end
if#acd==0 then
return nil
end
return string.format(NQe[4860],Wbd and NQe[4861]..(#acd==1 and NQe[4063]or NQe[4064])or NQe[1267],table.concat(acd,NQe[2739]))
end
function bb.lookAt(ecd)
local fcd,gcd=math.huge,nil
for hcd,icd in ipairs(bb.samples)do
local jcd=(U.flat(icd.pos)-U.flat(ecd)).Magnitude
if jcd<fcd then
fcd,gcd=jcd,icd.pos
end
end
local kcd=gcd and U.flat(gcd-ecd)or Vector3 .new(0,0,-1)
return kcd.Magnitude>0.01 and kcd.Unit or Vector3 .new(0,0,-1)
end
function bb.place(lcd,mcd)
local ncd=V.isFarm(lcd.id)
local ocd,pcd=bb.bestSpot(lcd,ncd or V.idol(lcd.id),(bb.trainee~=nil and lcd.uuid==bb.trainee)or V.ENTRY[lcd.id]==true or(O.takedownFront==true and V.takedownFed(lcd.id))or(bb.studyEntry==true and lcd.id==bb.trialId))
if not ocd then
bb.noSpot[lcd.uuid]=(bb.noSpot[lcd.uuid]or 0)+1
F.status(NQe[4716],NQe[4862]..V.name(lcd.id))
return false
end
local qcd=bb.money()
local rcd=P.caps[lcd.uuid]and bb.count(lcd.uuid)or nil
local scd,tcd=F.request(NQe[4848],NQe[4100],lcd.uuid,N.Util.CFramePLV(ocd,bb.lookAt(ocd)))
if scd and tcd then
if rcd and rcd>=(tonumber(P.caps[lcd.uuid])or math.huge)then
F.log(1,NQe[4653],string.format(NQe[4863],V.name(lcd.id),tostring(P.caps[lcd.uuid])))
P.caps[lcd.uuid],P.capsAt[lcd.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(lcd.data.cost or 0)
table.insert(bb.actions,string.format(NQe[4864],V.name(lcd.id)))
F.log(1,NQe[4653],string.format(NQe[4865],V.name(lcd.id),bb.spotKey(ocd),pcd,mcd))
bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=lcd.id,x=math.floor(ocd.X),z=math.floor(ocd.Z),cover=math.floor((pcd or 0)+0.5),why=tostring(mcd):sub(1,90)})
F.status(NQe[4716],string.format(NQe[4866],V.name(lcd.id),mcd))
bb.placedAt=bb.placedAt or{}
bb.placedAt[lcd.uuid]=(bb.placedAt[lcd.uuid]or 0)+1
return true
end
if qcd>=(lcd.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[lcd.uuid]=(bb.placeFail[lcd.uuid]or 0)+1
if bb.placeFail[lcd.uuid]>=2 then
bb.noSpot[lcd.uuid]=3
F.log(1,NQe[4653],string.format(NQe[4867],V.name(lcd.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if scd and qcd>=(lcd.data.cost or 0)and not bb.random then
local ucd=bb.spotKey(ocd)
bb.refused[ucd]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[lcd.uuid]=(bb.unitRefusals[lcd.uuid]or 0)+1
if not bb.crowded()then
local vcd=bb.mapKey()
P.blocked[vcd]=P.blocked[vcd]or{}
if not bb.refusedRun[ucd]then
P.blocked[vcd][ucd]=(tonumber(P.blocked[vcd][ucd])or 0)+1
bb.refusedRun[ucd]=true
P.blockedAt[vcd]=P.blockedAt[vcd]or{}
P.blockedAt[vcd][ucd]=os.time()
end
if bb.unitRefusals[lcd.uuid]>=3 then
local wcd=math.max(1,bb.count(lcd.uuid))
if P.caps[lcd.uuid]~=wcd or not V.learnedCap(lcd.uuid)then
P.caps[lcd.uuid],P.capsAt[lcd.uuid]=wcd,os.time()
F.log(1,NQe[4653],string.format(NQe[4868],V.name(lcd.id),wcd))
end
end
elseif bb.unitRefusals[lcd.uuid]>=3 and(bb.noSpot[lcd.uuid]or 0)<3 then
bb.noSpot[lcd.uuid]=3
F.log(1,NQe[4653],string.format(NQe[4869],V.name(lcd.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,NQe[4653],string.format(NQe[4870],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,NQe[4653],NQe[4871]..ucd..NQe[3331]..V.name(lcd.id))
F.saveSoon()
end
return false
end
function bb.crowded()
if bb.withOthers then
return true
end
return#game:GetService(NQe[1246]):GetPlayers()>1
end
bb.REFUSE_FREE,bb.REFUSE_PAUSE=10,20
function bb.placePaused()
return bb.placePause~=nil and U.now()<bb.placePause
end
function bb.count(xcd)
local ycd=0
for zcd,Acd in ipairs({workspace._UNITS,workspace:FindFirstChild(NQe[4648])})do
if Acd then
for Bcd,Ccd in ipairs(Acd:GetChildren())do
local Dcd=Ccd:FindFirstChild(NQe[2420])
if Dcd and Dcd:FindFirstChild(NQe[2740])and Dcd.player.Value==M and Dcd.uuid.Value==xcd then
ycd=ycd+1
end
end
end
end
return ycd
end
function bb.measure()
local Ecd,Fcd=bb.calRun,bb.info
if not(Ecd and Fcd)then
return
end
pcall(bb.sampleHelpers)
local Gcd=U.now()
local Hcd=bb.wave()
local Icd=bb.money()
if not Ecd.start and Icd>0 and#bb.mine==0 then
Ecd.start=Icd
end
if Hcd~=Ecd.lastW then
if bb.trialId and Hcd>0 then
bb.trialTrace=bb.trialTrace or{}
local Jcd,Kcd,Lcd,Mcd=0,{},0,0
for Ncd,Ocd in ipairs(bb.mine)do
local Pcd=Ocd._stats
if Pcd.id.Value==bb.trialId then
Jcd=Jcd+1
table.insert(Kcd,tostring(Pcd.upgrade.Value))
elseif not V.isFarm(Pcd.id.Value)then
Mcd=Mcd+1
end
end
pcall(bb.sampleHelpers,true)
for Qcd,Rcd in pairs(bb.ownDealt)do
if Rcd.id==bb.trialId then
Lcd=Lcd+Rcd.v
end
end
local Scd=0
for Tcd,Ucd in pairs(bb.helperDealt)do
if Ucd.owner==bb.trialId then
Scd=Scd+Ucd.v
end
end
table.insert(bb.trialTrace,string.format(NQe[4872],Hcd,Gcd-(bb.startT or Gcd),Icd,table.concat(Kcd,NQe[3055]),Mcd,Lcd+Scd,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[Hcd-1]or 0,bb.teamDps or 0))
end
if Ecd.lastW and Ecd.lastW>0 and Ecd.lastWT then
table.insert(Ecd.waveSec,Gcd-Ecd.lastWT)
end
if Ecd.paidT and Hcd>0 and Gcd-Ecd.paidT<15 then
table.insert(Ecd.skip,Gcd-Ecd.paidT)
end
Ecd.paidT=nil
if Hcd>0 then
Ecd.alive[tostring(Hcd)]=bb.hpAliveRaw or 0
end
Ecd.lastW,Ecd.lastWT=Hcd,Gcd
end
local Vcd=workspace:FindFirstChild(NQe[4873])
if Vcd and Hcd>0 then
Ecd.timer[tostring(Hcd)]=math.max(Ecd.timer[tostring(Hcd)]or 0,tonumber(Vcd.Value)or 0)
end
local Wcd=tonumber(bb.spent)or 0
local Xcd=Icd-(bb.lastMoneyR or Icd)+(Wcd-(bb.lastSpentR or Wcd))
bb.lastMoneyR,bb.lastSpentR=Icd,Wcd
bb.incomeLog=bb.incomeLog or{}
if Xcd>0 then
table.insert(bb.incomeLog,{t=Gcd,y=Xcd})
end
while bb.incomeLog[1]and Gcd-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local Ycd=0
for Zcd,_cd in ipairs(bb.incomeLog)do
Ycd=Ycd+_cd.y
end
local bdd=math.min(30,Gcd-(bb.startT or Gcd))
bb.incomeRate=bdd>=8 and Ycd/bdd or nil
for cdd,ddd in ipairs(bb.enemies)do
local edd=ddd.m
local fdd=bb.track[edd]
if not fdd then
local gdd=edd._stats
local hdd=edd:FindFirstChildOfClass(NQe[2757])
local idd=Fcd.cfgById[gdd.id.Value]
local jdd=idd and gb.baseStats(Fcd,idd)
if hdd and jdd and Hcd>0 then
local kdd=jdd*Fcd.hpRaw*gb.waveScale(Fcd,Hcd,Fcd.list[Hcd])
if kdd>0 and hdd.MaxHealth>0 then
table.insert(Ecd.hp,hdd.MaxHealth/kdd)
end
