bb.track[edd]={t=Gcd,p=ddd.prog,sp=(gdd:FindFirstChild(NQe[4874])and tonumber(gdd.speed.Value))or 1}
if hdd and hdd.MaxHealth>0 then
bb.enemyHpSum=(bb.enemyHpSum or 0)+hdd.MaxHealth
end
if Hcd>0 then
Ecd.spawn[tostring(Hcd)]=(Ecd.spawn[tostring(Hcd)]or 0)+1
Ecd.spawnLast[tostring(Hcd)]=Gcd-(Ecd.lastWT or Gcd)
end
elseif not fdd.done and Gcd-fdd.t>=15 then
fdd.done=true
local ldd=(ddd.prog-fdd.p)/(Gcd-fdd.t)/math.max(0.1,fdd.sp)
