local tdd=0
Ecd.potBy=Ecd.potBy or{}
Ecd.potExp=Ecd.potExp or{}
for udd,vdd in ipairs(bb.mine)do
local wdd=vdd._stats
local xdd=wdd.id.Value
if not V.isFarm(xdd)and((wdd:FindFirstChild(NQe[4875])and wdd.target.Value~=nil)or bb.inReach(vdd,xdd))then
local ydd,zdd=pcall(bb.liveDps,vdd,xdd)
if ydd and zdd then
tdd=tdd+zdd*sdd
local Add=math.max(0.5,V.nudge(xdd))
local Bdd=zdd/Add
local Cdd,Ddd=pcall(function()
return V.passive(xdd).mark
end)
if Cdd and Ddd and wdd:FindFirstChild(NQe[2798])then
Bdd=Bdd+(tonumber(Ddd.dot)or 0)*wdd.damage.Value
end
Ecd.potBy[xdd]=(Ecd.potBy[xdd]or 0)+Bdd*sdd
Ecd.potExp[xdd]=(Ecd.potExp[xdd]or 0)+Bdd*Add*sdd
end
end
end
Ecd.potWin=(Ecd.potWin or 0)+tdd
if Gcd-(Ecd.winT or Gcd)>=5 then
