table.insert(Gtd,string.format(NQe[5034],tostring(Htd),tostring(type(Itd)==NQe[2348]and Itd.title or NQe[2599]),(type(Itd)==NQe[2348]and Itd.weather)and(NQe[3086]..tostring(Itd.weather)..NQe[3029])or NQe[1267],tostring(type(Itd)==NQe[2348]and Itd.option_type or NQe[2599]),Jtd,math.floor(Otd+0.5),table.concat(Ktd,NQe[3000])))
