if Evd==NQe[2910]then
return 1,math.abs(Fvd)
end
if Evd==NQe[4439]or Evd==NQe[4444]or Evd==NQe[4440]then
if Gvd==NQe[2798]then
return math.max(0.3,1+Fvd),0
end
if Gvd==NQe[2616]then
return math.max(0.5,1+Fvd/2),0
end
if Gvd:find(NQe[3168])then
return 1/math.max(0.3,1+Fvd),0
end
