if Evd==NQe[5068]then
return math.max(0.5,1-Fvd*0.5),0
end
if Evd==NQe[5069]then
return math.max(0.5,1-Fvd*0.2),0
end
if Evd==NQe[5070]then
return 1+Fvd*0.1,0
end
if Evd==NQe[5071]then
return 1/math.max(0.3,1+Fvd*0.5),0
end
if Evd==NQe[5072]then
return math.max(0.5,1-Fvd*0.1),0
end
if Evd==NQe[4447]then
return 1/math.max(0.3,1+Fvd),0
end
if Evd==NQe[4453]then
return math.max(0.3,1-Fvd*20),0
end
if Evd==NQe[4454]then
