function bb.learn()
local Jvd=bb.calRun and bb.calRun.potBy
if type(Jvd)~=NQe[2348]then
return
end
pcall(bb.sampleHelpers,true)
local Kvd={}
for Lvd,Mvd in pairs(bb.ownDealt or{})do
if not V.isFarm(Mvd.id)then
Kvd[Mvd.id]=(Kvd[Mvd.id]or 0)+(tonumber(Mvd.v)or 0)
end
end
for Nvd,Ovd in pairs(bb.helperDealt or{})do
if Ovd.owner and V.SUMMONER[Ovd.owner]and not V.droneHelper(Ovd)then
Kvd[Ovd.owner]=(Kvd[Ovd.owner]or 0)+(tonumber(Ovd.v)or 0)
end
end
local Pvd=type(bb.calRun.potExp)==NQe[2348]and bb.calRun.potExp or{}
local Qvd,Rvd=0,0
local Svd={}
for Tvd,Uvd in pairs(Jvd)do
if Uvd>0 then
Qvd,Rvd=Qvd+(Kvd[Tvd]or 0),Rvd+Uvd
local Vvd=tonumber(Pvd[Tvd])or Uvd
if Vvd>0 then
table.insert(Svd,{id=Tvd,r=(Kvd[Tvd]or 0)/Vvd,w=Vvd})
end
end
end
if Qvd<=0 or Rvd<=0 then
return
end
table.sort(Svd,function(Wvd,Xvd)
return Wvd.r<Xvd.r
end)
local function Yvd(Zvd)
local _vd,awd=0,0
for bwd,cwd in ipairs(Svd)do
if cwd.id~=Zvd then
_vd=_vd+cwd.w
end
end
if _vd<=0 then
return nil
end
for dwd,ewd in ipairs(Svd)do
if ewd.id~=Zvd then
awd=awd+ewd.w
if awd>=_vd/2 then
return ewd.r
end
end
end
end
bb.lastEff={}
for fwd,gwd in pairs(Jvd)do
local hwd=Yvd(fwd)
if gwd>0 and gwd/Rvd>0.02 and hwd and hwd>0 then
local iwd=P.learn[fwd]or{eff=1,n=0,v=6}
V.learnUp(fwd,iwd)
local jwd=math.max(0.02,0.25*math.sqrt(30/(30+iwd.n)))
local kwd=U.clamp(((Kvd[fwd]or 0)/gwd)/hwd,0.2,6)
bb.lastEff[fwd]=math.floor(kwd*1000+0.5)/1000
iwd.eff=iwd.eff+(kwd-iwd.eff)*jwd
iwd.n=iwd.n+1
P.learn[fwd]=iwd
end
end
local lwd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if lwd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==NQe[2348]and P.mapLearn or{}
local mwd=type(P.mapLearn[lwd])==NQe[2348]and P.mapLearn[lwd]or{}
for nwd,owd in pairs(bb.lastEff)do
local pwd=type(mwd[nwd])==NQe[2348]and mwd[nwd]or{eff=owd,n=0,v=6}
if(tonumber(pwd.v)or 0)<4 then
pwd.eff,pwd.v=(tonumber(pwd.eff)or owd)*V.secRescale(nwd),4
end
if(tonumber(pwd.v)or 0)<5 then
pwd.eff,pwd.v=(tonumber(pwd.eff)or owd)*(V.sumRescale(nwd)or 1),5
end
if(tonumber(pwd.v)or 0)<6 then
pwd.eff,pwd.v=(tonumber(pwd.eff)or owd)*(1-(V.SUMMONER[nwd]and V.SUMMONER[nwd].droneShare or 0)),6
end
local qwd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(pwd.n)or 0))))
pwd.eff=(tonumber(pwd.n)or 0)==0 and owd or((tonumber(pwd.eff)or owd)+(owd-(tonumber(pwd.eff)or owd))*qwd)
pwd.n=(tonumber(pwd.n)or 0)+1
mwd[nwd]=pwd
end
mwd._at=os.time()
P.mapLearn[lwd]=mwd
if U.count(P.mapLearn)>80 then
local rwd,swd
for twd,uwd in pairs(P.mapLearn)do
if not swd or(tonumber(uwd._at)or 0)<swd then
rwd,swd=twd,tonumber(uwd._at)or 0
end
end
P.mapLearn[rwd]=nil
end
end
end
