bb.upRate=setmetatable({},{__mode=NQe[2748]})
function bb.refund()
local YBd=N.session()
if not(bb.random and YBd)or bb.spellBusy or bb.roomPlan or not ab.every(NQe[5160],20)then
return
end
local ZBd
for _Bd,aCd in pairs(YBd.ingame_spells or{})do
if aCd==NQe[5147]then
ZBd=_Bd
end
end
if not ZBd then
return
end
local bCd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local cCd=bb.bestRate or 0
if bCd or cCd<=0 then
return
end
local dCd=bb.wave()
local eCd=math.max(0,(bb.total or 30)-dCd)
local fCd=bb.mergePlan
local gCd=bb.airLow()
local hCd,iCd,jCd
for kCd,lCd in ipairs(bb.mine)do
local mCd=lCd._stats
local nCd=mCd.id.Value
local oCd=N.Units[nCd]
local pCd=mCd:FindFirstChild(NQe[4655])and tonumber(mCd.total_spent.Value)or 0
if oCd and not oCd.unsellable and pCd>0 and not V.allyBuff(nCd)and not V.idol(nCd)and not(fCd and fCd.id==nCd)then
local qCd,rCd
if V.isFarm(nCd)then
local sCd=mCd:FindFirstChild(NQe[2468])and tonumber(mCd.farm_amount.Value)or 0
local tCd=sCd*eCd
if pCd>tCd*1.2 then
qCd=(pCd-tCd)*cCd
rCd=string.format(NQe[5161],U.fmt(tCd),U.fmt(pCd))
end
elseif dCd>=10 and eCd>2 and pCd>=5000 and(bb.upRate[lCd]or 0)<cCd/3 and bb.progressAt(lCd:GetPivot().Position)<0.8 and not(gCd and bb.canAir(lCd))then
local uCd,vCd=pcall(bb.liveDps,lCd,nCd)
vCd=uCd and vCd or math.huge
if pCd*cCd>3*vCd and vCd<0.1*(bb.teamDps or 0)then
qCd=pCd*cCd-vCd
rCd=string.format(NQe[5162],U.fmt(pCd))
end
end
if qCd and(not iCd or qCd>iCd)then
hCd,iCd,jCd=lCd,qCd,rCd
end
end
end
if not hCd then
return
end
bb.spellBusy=true
task.spawn(function()
local wCd=V.name(hCd._stats.id.Value)
local xCd=F.request(NQe[5153],NQe[5154],ZBd,hCd)
task.wait(1.5)
if xCd and(N.session().ingame_spells or{})[ZBd]~=NQe[5147]then
bb.refunds=(bb.refunds or 0)+1
F.log(1,NQe[5133],string.format(NQe[5163],wCd,jCd))
F.status(NQe[5016],NQe[5164]..wCd)
else
F.backoff(NQe[5153],15)
F.log(2,NQe[5133],NQe[5165]..wCd)
end
bb.spellBusy=false
end)
end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(yCd,zCd)
local ACd=(zCd.t or 0)-(yCd.t or 0)
if ACd<bb.BASE_WIN-1 then
return false
end
local BCd=((tonumber(yCd.base)or 0)-(tonumber(zCd.base)or 0))/ACd
if BCd<=0 or(tonumber(zCd.base)or 0)<=0 then
return false
end
local CCd=zCd.base/BCd
local DCd,ECd=0,0
local FCd,GCd=yCd.foes or{},zCd.foes or{}
for HCd,ICd in pairs(GCd)do
if ICd.prog>=bb.BASE_END then
DCd=DCd+ICd.hp
local JCd=FCd[HCd]
if JCd then
ECd=ECd+math.max(0,JCd.hp-ICd.hp)
end
end
end
for KCd,LCd in pairs(FCd)do
if LCd.prog>=bb.BASE_END and not GCd[KCd]then
ECd=ECd+LCd.hp
end
end
if DCd<=0 then
return false
end
local MCd=ECd/ACd
local NCd=MCd>0 and DCd/MCd or math.huge
local OCd={baseTime=CCd,loss=BCd,atEnd=DCd,rate=MCd,killTime=NCd}
return CCd<bb.BASE_SOON and NCd>CCd*bb.BASE_MARGIN,OCd
end
