F.log(1,NQe[3036],string.format(NQe[5179],bb.wave(),tonumber(bb.total)or 0,math.floor(100*hDd.base/math.max(1,hDd.baseMax)+0.5),U.fmt(mDd.loss),math.floor(mDd.baseTime),U.fmt(mDd.atEnd),U.fmt(mDd.rate),mDd.killTime==math.huge and NQe[4921]or(math.floor(mDd.killTime)..NQe[2194])))
pcall(F.saveNow)
