end
bb.LEAK_WIN,bb.LEAK_SOON,bb.LEAK_MIN,bb.LEAK_MARGIN,bb.LEAK_AHEAD=3,12,3,1.5,6
function bb.leakAhead(nDd)
local oDd=0
local pDd=U.flat(nDd.pos)
for qDd,rDd in ipairs(bb.mine or{})do
local sDd=rDd:FindFirstChild(NQe[2420])
local tDd=sDd and sDd:FindFirstChild(NQe[2741])
local uDd=sDd and sDd:FindFirstChild(NQe[2616])
if tDd and uDd and not V.isFarm(tDd.Value)and not V.allyBuff(tDd.Value)then
local vDd,wDd=U.flat(rDd:GetPivot().Position),uDd.Value
if(not nDd.fly or bb.canAir(rDd))and(vDd-pDd).Magnitude>wDd then
for xDd,yDd in ipairs(bb.samples or{})do
if yDd.prog>nDd.prog and(U.flat(yDd.pos)-vDd).Magnitude<=wDd then
oDd=oDd+1
break
end
end
end
end
end
return oDd
end
function bb.leakStep(zDd)
if not zDd then
if bb.kind~=NQe[2374]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local ADd=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==NQe[2348]and P.dg.bails or{}
if not zDd and(tonumber(P.dg.bails[ADd])or 0)>=bb.BAIL_MAX then
return
end
local BDd=workspace:FindFirstChild(NQe[5178])and workspace._BASES:FindFirstChild(NQe[4612])
local CDd=BDd and BDd:FindFirstChild(NQe[4876])and BDd.base:FindFirstChild(NQe[4877])
local DDd=CDd and CDd:FindFirstChildOfClass(NQe[2757])
if not DDd or DDd.Health<=0 then
return
end
local EDd=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local FDd=U.now()
bb.leakTrack=bb.leakTrack or{}
local GDd=bb.leakTrack
local HDd,IDd={},nil
for JDd,KDd in ipairs(bb.enemies or{})do
if KDd.m then
HDd[KDd.m]=true
local LDd,MDd=tonumber(KDd.hp)or 0,tonumber(KDd.prog)or 0
local NDd=GDd[KDd.m]
if not NDd then
GDd[KDd.m]={t=FDd,hp=LDd,prog=MDd}
else
if FDd-NDd.t>=bb.LEAK_WIN then
NDd.pace,NDd.net=(MDd-NDd.prog)/(FDd-NDd.t),(NDd.hp-LDd)/(FDd-NDd.t)
NDd.t,NDd.hp,NDd.prog=FDd,LDd,MDd
end
if NDd.pace and NDd.pace>0 and LDd>0 then
local ODd=(1-MDd)/NDd.pace
local PDd=math.max(0,NDd.net or 0)
local QDd=LDd-PDd*ODd
if QDd>0 and ODd<=bb.LEAK_SOON and ODd>=bb.LEAK_MIN then
local RDd=KDd.m:FindFirstChildOfClass(NQe[2757])
local SDd=DDd.Health/math.max(1,EDd*(RDd and RDd.MaxHealth or LDd))
local TDd=PDd>0 and QDd/PDd or math.huge
if TDd>SDd*bb.LEAK_MARGIN and(ODd<=bb.LEAK_AHEAD or bb.leakAhead(KDd)==0)and(not IDd or ODd<IDd.left)then
IDd={left=ODd,arriving=QDd,net=PDd,baseTime=SDd,hp=LDd}
end
end
end
end
end
end
for UDd in pairs(GDd)do
if not HDd[UDd]then
GDd[UDd]=nil
end
end
if zDd then
return IDd~=nil,IDd
end
if not IDd then
return
end
bb.bailNote(ADd,NQe[5172])
F.log(1,NQe[3036],string.format(NQe[5181],bb.wave(),tonumber(bb.total)or 0,math.floor(IDd.left+0.5),U.fmt(IDd.hp),U.fmt(IDd.arriving),U.fmt(IDd.net),IDd.baseTime))
pcall(F.saveNow)
bb.toLobby(NQe[5180])
end
