function bb.allPast(VDd)
local WDd={}
for XDd,YDd in ipairs(bb.mine or{})do
local ZDd=YDd._stats
local _Dd=ZDd.id.Value
if not V.isFarm(_Dd)and not V.allyBuff(_Dd)and ZDd:FindFirstChild(NQe[2616])then
local aEd=tonumber(ZDd.range.Value)or 0
local bEd=bb.coverMax[YDd]
if not(bEd and bEd.r==aEd)then
local cEd,dEd=U.flat(YDd:GetPivot().Position),-1
for eEd,fEd in ipairs(bb.samples or{})do
if fEd.prog>dEd and(U.flat(fEd.pos)-cEd).Magnitude<=aEd then
dEd=fEd.prog
end
end
bEd={r=aEd,far=dEd}
bb.coverMax[YDd]=bEd
end
table.insert(WDd,{far=bEd.far,air=bb.canAir(YDd)})
end
end
if#WDd==0 then
return false
end
for gEd,hEd in ipairs(VDd)do
for iEd,jEd in ipairs(WDd)do
if(not hEd.fly or jEd.air)and jEd.far>=(tonumber(hEd.prog)or 0)then
return false
end
end
end
return true
end
function bb.fbTick()
local kEd=bb.info and bb.info.final
if not(kEd and kEd.cfg)then
return
end
local lEd=type(bb.info.configs)==NQe[2348]and bb.info.configs[kEd.cfg]
local mEd=type(lEd)==NQe[2348]and lEd.unit_id or kEd.cfg
local nEd
for oEd,pEd in ipairs(bb.enemies or{})do
local qEd=pEd.m and pEd.m:FindFirstChild(NQe[2420])
if qEd and qEd:FindFirstChild(NQe[2741])and qEd.id.Value==mEd then
nEd=pEd
break
end
end
local rEd=bb.fb
if not nEd then
if rEd and not rEd.gone then
rEd.gone=U.now()
end
return
end
local sEd=nEd.m:FindFirstChildOfClass(NQe[2757])
local tEd=(sEd and sEd.MaxHealth>0)and sEd.MaxHealth or nEd.hp
local uEd=(N.Units[mEd]and N.Units[mEd].name)or mEd
if not rEd or rEd.m~=nEd.m then
rEd={m=nEd.m,id=mEd,name=uEd,wave=bb.wave(),t0=U.now(),max=tEd,low=1,assassin=kEd.assassin,beatAt=tonumber(kEd.beatAt)or 0.5,walk=kEd.walk}
bb.fb=rEd
if kEd.assassin then
F.log(1,NQe[3036],string.format(NQe[5182],uEd,rEd.wave,U.fmt(tEd),math.floor(rEd.beatAt*100+0.5)))
end
end
rEd.e=nEd
rEd.share=tEd>0 and nEd.hp/tEd or 1
rEd.low=math.min(rEd.low,rEd.share)
local vEd,wEd=pcall(N.PATH.get_unit_path_progress,nEd.m)
rEd.gp=vEd and tonumber(wEd)or nil
if rEd.assassin and not rEd.beaten and rEd.share<=rEd.beatAt+0.005 then
rEd.beaten=U.now()
F.log(1,NQe[3036],string.format(NQe[5183],uEd,math.floor(rEd.share*100+0.5)))
end
if#(bb.enemies or{})==1 and bb.total and bb.wave()>=bb.total then
rEd.aloneT=rEd.aloneT or U.now()
rEd.alone=math.max(rEd.alone or 0,U.now()-rEd.aloneT)
else
rEd.aloneT=nil
end
end
function bb.fbEnd(xEd)
local yEd=bb.fb
if not yEd then
return nil
end
local function zEd(AEd)
return AEd and math.floor(AEd*1000+0.5)/1000 or nil
end
